type View = "signin" | "forgot" | "forgot-sent";
type Persona = "web" | "admin";

export default function LoginClient({ strings: s }: { strings: LoginStrings }) {
  const [view, setView] = useState<View>("signin");
  const [persona, setPersona] = useState<Persona>("web");

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function signIn(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true); setError(null);
    const { error } = await supabaseBrowser().auth.signInWithPassword({ email, password });
    setBusy(false);
    if (error) { setError(error.message); return; }  // ERR-AUTH-001: deny with safe message
    // Hard navigation: guarantees the auth cookie is on the request before
    // the destination renders server-side (router.push races the cookie
    // write). The persona picks the console; role guards still decide.
    window.location.assign(persona === "admin" ? "/admin" : "/launch");
  }

  async function sendReset(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true); setError(null);
    // Supabase Auth sends the recovery email via its own mailer; the link
    // lands on /reset where the user sets a new password. redirectTo must be
    // in the project's auth redirect allowlist.
    const { error } = await supabaseBrowser().auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/reset`,
    });
    setBusy(false);
    // Do not reveal whether the address exists (anti-enumeration): always
    // advance to the neutral "check your inbox" confirmation on success OR
    // a non-committal failure. Only surface transport errors.
    if (error) { setError(error.message); return; }
    // Audit the request (FND-003). Best-effort; the entered address is hashed
    // client-side and never stored raw. Fire regardless of account existence.
    void logAuthEvent("password_reset_requested", email);
    setView("forgot-sent");
  }

  return (
    <div className="lg-page lg-page--split" dir={s.dir} lang={s.lang}>
      <aside className="lg-brand" aria-hidden="true">
        <div className="lg-brand__head">
          <span className="lg-brand__wordmark" lang="ar" dir="rtl">{s.wordmark}</span>
          <span className="lg-brand__latin">{s.wordmarkLatin}</span>
        </div>
        <div className="lg-brand__live">
          <span className="lg-brand__livedot" />
          {s.liveLabel}
        </div>
        <KsaMap />
        <div className="lg-brand__stats">
          <div className="lg-brand__stat">
            <strong>3,102</strong>
            <span>{s.statFactories}</span>
          </div>
          <div className="lg-brand__stat">
            <strong>312</strong>
            <span>{s.statInspectors}</span>
          </div>
        </div>
        <p className="lg-brand__tagline">
          {s.tagline.map(line => <span key={line}>{line}</span>)}
        </p>
      </aside>

      <main className="lg-panel">
        <header className="lg-topbar">
          <span className="lg-topbar__brand" lang="ar" dir="rtl">{s.wordmark}</span>
          <a className="lg-lang" href={s.langHref}>{s.langLabel}</a>
        </header>

        <div className="lg-center">
          {view === "signin" && (
            <section className="lg-card" aria-label={s.cardTitle}>
              <h1 className="lg-card__title">{s.cardTitle}</h1>
              <p className="lg-card__sub">{s.cardSub}</p>

              <fieldset className="lg-persona">
                <legend className="lg-persona__label">{s.personaLabel}</legend>
                <div className="lg-persona__grid" role="radiogroup" aria-label={s.personaLabel}>
                  <button type="button" role="radio" aria-checked={persona === "web"}
                    className={persona === "web" ? "lg-persona__opt lg-persona__opt--active" : "lg-persona__opt"}
                    onClick={() => setPersona("web")}>
                    <strong>{s.personaWebTitle}</strong>
                    <span>{s.personaWebSub}</span>
                  </button>
                  <button type="button" role="radio" aria-checked={persona === "admin"}
                    className={persona === "admin" ? "lg-persona__opt lg-persona__opt--active" : "lg-persona__opt"}
                    onClick={() => setPersona("admin")}>
                    <strong>{s.personaAdminTitle}</strong>
                    <span>{s.personaAdminSub}</span>
                  </button>
                </div>
              </fieldset>

              <form className="lg-credentials" onSubmit={signIn}>
                <div className="ax-field">
                  <label className="ax-field__label" htmlFor="email">{s.idLabel}</label>
                  <input id="email" className="ax-input" type="email" autoComplete="username"
                    placeholder={s.idPlaceholder} value={email}
                    onChange={e => setEmail(e.target.value)} required />
                </div>
                <div className="ax-field">
                  <label className="ax-field__label" htmlFor="pw">{s.pwLabel}</label>
                  <div className="lg-pwwrap">
                    <input id="pw" className="ax-input" type={showPw ? "text" : "password"}
                      autoComplete="current-password" placeholder={s.pwPlaceholder} value={password}
                      onChange={e => setPassword(e.target.value)} required />
                    <button type="button" className="lg-pwtoggle" onClick={() => setShowPw(v => !v)}
                      aria-label={showPw ? s.hidePw : s.showPw}>
                      {showPw ? <IconEyeOff /> : <IconEye />}
                    </button>
                  </div>
                </div>
                {error && <div className="ax-banner ax-banner--critical" role="alert">{error}</div>}
                <button className="ax-btn ax-btn--prominent lg-submit" type="submit" disabled={busy}>
                  {busy ? s.signingIn : s.signIn}
                </button>
                <button type="button" className="lg-linkbtn" onClick={() => { setError(null); setView("forgot"); }}>
                  {s.forgotLink}
                </button>
              </form>
            </section>
          )}

          {view === "forgot" && (
            <section className="lg-card" aria-label={s.forgotTitle}>
              <h1 className="lg-card__title">{s.forgotTitle}</h1>
              <p className="lg-card__sub">{s.forgotSub}</p>
              <form className="lg-credentials" onSubmit={sendReset}>
                <div className="ax-field">
                  <label className="ax-field__label" htmlFor="email">{s.idLabel}</label>
                  <input id="email" className="ax-input" type="email" autoComplete="username"
                    placeholder={s.idPlaceholder} value={email}
                    onChange={e => setEmail(e.target.value)} required />
                </div>
                {error && <div className="ax-banner ax-banner--critical" role="alert">{error}</div>}
                <button className="ax-btn ax-btn--prominent lg-submit" type="submit" disabled={busy}>
                  {busy ? s.forgotSending : s.forgotSend}
                </button>
                <button type="button" className="lg-linkbtn" onClick={() => { setError(null); setView("signin"); }}>
                  {s.back}
                </button>
              </form>
            </section>
          )}

          {view === "forgot-sent" && (
            <section className="lg-card" aria-label={s.forgotSentTitle}>
              <h1 className="lg-card__title">{s.forgotSentTitle}</h1>
              <p className="lg-card__sub">{s.forgotSentBody}</p>
              <button type="button" className="lg-linkbtn" onClick={() => { setError(null); setView("signin"); }}>
                {s.back}
              </button>
            </section>
          )}
        </div>

        <footer className="lg-foot">
          <span className="lg-foot__item"><IconShieldCheck /> {s.footTrust}</span>
          <span className="lg-foot__item"><IconLock /> {s.footSecure}</span>
          <span className="lg-foot__copy">{s.footCopyright}</span>
        </footer>
      </main>
    </div>
  );
}

/* ============================================================================
   SAQEEL — UNIFIED SIGN-IN (SCR-PUB-010 v2)
   Pattern: launch-film split layout — brand panel (wordmark, KSA coverage
   motif, tagline) beside a single credential form with a persona selector.
   GLOBAL COLOR LAW: tokens only — every color is var(--ax-*) or a color-mix()
   of approved tokens. No raw values outside tokens.css.
   Shared with /reset: .lg-page (base), .lg-topbar, .lg-center, .lg-card,
   .lg-credentials, .lg-pwwrap, .lg-pwtoggle, .lg-submit, .lg-waiting.
   ========================================================================== */

.lg-page { min-block-size: 100dvh; display: flex; flex-direction: column;
  background: var(--ax-color-canvas);
  color: var(--ax-color-text); font: var(--ax-text-body); }

/* Split variant (login): brand panel + form panel */
.lg-page--split { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(420px, 1fr); }
@media (max-width: 960px) { .lg-page--split { grid-template-columns: 1fr; } }

/* ---- brand panel ---------------------------------------------------- */
.lg-brand { position: relative; overflow: hidden; display: flex; flex-direction: column;
  gap: var(--ax-space-300); padding: clamp(24px, 4vw, 56px);
  background:
    radial-gradient(120% 90% at 15% 0%,
      color-mix(in srgb, var(--ax-color-primary) 12%, transparent), transparent 60%),
    var(--ax-color-canvas);
  border-inline-end: 1px solid var(--ax-color-border); }
@media (max-width: 960px) { .lg-brand { display: none; } }

.lg-brand__head { display: flex; flex-direction: column; gap: var(--ax-space-050); }
.lg-brand__wordmark { font: 700 40px/1.2 var(--ax-font-arabic); color: var(--ax-color-text); }
.lg-brand__latin { font: var(--ax-text-micro); letter-spacing: 0.18em;
  color: var(--ax-color-text-secondary); text-transform: uppercase; }

.lg-brand__live { display: inline-flex; align-items: center; gap: var(--ax-space-100);
  font: var(--ax-text-micro); letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--ax-color-success); }
.lg-brand__livedot { inline-size: 8px; block-size: 8px; border-radius: var(--ax-radius-full);
  background: var(--ax-color-success);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--ax-color-success) 25%, transparent);
  animation: lg-pulse 2.4s ease-in-out infinite; }
@keyframes lg-pulse { 50% { box-shadow: 0 0 0 8px color-mix(in srgb, var(--ax-color-success) 10%, transparent); } }

.lg-brand__stats { display: flex; gap: var(--ax-space-300); }
.lg-brand__stat { flex: 0 1 220px; display: flex; flex-direction: column; gap: var(--ax-space-050);
  padding: var(--ax-space-250) var(--ax-space-300);
  background: color-mix(in srgb, var(--ax-color-surface) 72%, transparent);
  border: 1px solid var(--ax-color-border); border-radius: var(--ax-radius-standard); }
.lg-brand__stat strong { font: 600 30px/38px var(--ax-font-sans);
  font-feature-settings: var(--ax-numeric-features); color: var(--ax-color-text); }
.lg-brand__stat span { font: var(--ax-text-micro); letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--ax-color-text-secondary); }

.lg-brand__tagline { margin-block-start: auto; display: flex; flex-direction: column;
  gap: var(--ax-space-050); font: 500 22px/32px var(--ax-font-sans);
  color: var(--ax-color-text-secondary); }
.lg-brand__tagline span:first-child { color: var(--ax-color-text); }

/* ---- national coverage motif ---------------------------------------- */
.lg-map { inline-size: min(100%, 560px); block-size: auto; margin-block: var(--ax-space-100); }
.lg-map__fill { fill: color-mix(in srgb, var(--ax-color-primary) 8%, transparent); stroke: none; }
.lg-map__outline { fill: none; stroke: color-mix(in srgb, var(--ax-color-primary) 70%, transparent);
  stroke-width: 1.5; stroke-linejoin: round; }
.lg-map__label { font: 500 13px var(--ax-font-mono); fill: var(--ax-color-text-secondary); }
.lg-map__ring { fill: none; stroke-width: 5; opacity: 0.35; }
.lg-map__dot { stroke: none; }
.lg-map__halo { stroke: none; opacity: 0.16; }
.lg-map__city--ok   .lg-map__dot,  .lg-map__city--ok   .lg-map__halo { fill: var(--ax-color-success); }
.lg-map__city--ok   .lg-map__ring  { stroke: var(--ax-color-success); }
.lg-map__city--due  .lg-map__dot,  .lg-map__city--due  .lg-map__halo { fill: var(--ax-color-warning); }
.lg-map__city--due  .lg-map__ring  { stroke: var(--ax-color-warning); }
.lg-map__city--risk .lg-map__dot,  .lg-map__city--risk .lg-map__halo { fill: var(--ax-color-critical); }
.lg-map__city--risk .lg-map__ring  { stroke: var(--ax-color-critical); }

/* ---- form panel ------------------------------------------------------ */
.lg-panel { display: flex; flex-direction: column; min-inline-size: 0;
  background: var(--ax-color-canvas); }

.lg-topbar { display: flex; align-items: center; justify-content: space-between;
  padding: var(--ax-space-250) clamp(20px, 4vw, 48px); }
.lg-topbar__brand { font: 700 20px/28px var(--ax-font-arabic); color: var(--ax-color-text); }
.lg-topbar__brandtext { display: flex; flex-direction: column; }
.lg-lang { font: var(--ax-text-body-strong); color: var(--ax-color-primary-hover);
  text-decoration: none; }
.lg-lang:hover { text-decoration: underline; text-underline-offset: 3px; }

.lg-center { flex: 1; display: grid; place-items: center;
  padding: var(--ax-space-300) clamp(20px, 4vw, 48px); }

.lg-card { inline-size: min(100%, 460px); display: flex; flex-direction: column;
  gap: var(--ax-space-200); padding: clamp(24px, 3vw, 40px);
  background: var(--ax-color-surface); border: 1px solid var(--ax-color-border);
  border-radius: var(--ax-radius-large); box-shadow: var(--ax-shadow-raised); }
.lg-card__title { margin: 0; font: var(--ax-text-title); color: var(--ax-color-text); }
.lg-card__sub { margin: 0; font: var(--ax-text-body); color: var(--ax-color-text-secondary); }

/* ---- persona selector ------------------------------------------------ */
.lg-persona { margin: 0; padding: 0; border: none;
  display: flex; flex-direction: column; gap: var(--ax-space-100); }
.lg-persona__label { padding: 0; font: var(--ax-text-micro); letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--ax-color-text-secondary); }
.lg-persona__grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--ax-space-150); }
@media (max-width: 420px) { .lg-persona__grid { grid-template-columns: 1fr; } }
.lg-persona__opt { display: flex; flex-direction: column; gap: var(--ax-space-050);
  padding: var(--ax-space-150) var(--ax-space-200); text-align: start; cursor: pointer;
  background: var(--ax-color-surface-sunken); border: 1px solid var(--ax-color-border);
  border-radius: var(--ax-radius-standard);
  transition: border-color var(--ax-motion-fast), background var(--ax-motion-fast); }
.lg-persona__opt:hover { border-color: var(--ax-color-border-strong); }
.lg-persona__opt:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }
.lg-persona__opt--active { background: var(--ax-color-primary-tint);
  border-color: var(--ax-color-primary); }
.lg-persona__opt strong { font: var(--ax-text-body-strong); color: var(--ax-color-text); }
.lg-persona__opt span { font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }

/* ---- credential form -------------------------------------------------- */
.lg-credentials { display: flex; flex-direction: column; gap: var(--ax-space-200); }
.lg-pwwrap { position: relative; }
.lg-pwwrap .ax-input { padding-inline-end: 48px; }
.lg-pwtoggle { position: absolute; inset-block-start: 50%; inset-inline-end: var(--ax-space-100);
  transform: translateY(-50%); display: grid; place-items: center;
  inline-size: 36px; block-size: 36px; border: none; border-radius: var(--ax-radius-small);
  background: none; color: var(--ax-color-text-secondary); cursor: pointer; }
.lg-pwtoggle:hover { color: var(--ax-color-text); background: var(--ax-color-neutral-tint); }
.lg-submit { inline-size: 100%; }
.lg-linkbtn { align-self: center; background: none; border: none; padding: 0; cursor: pointer;
  font: var(--ax-text-body-strong); color: var(--ax-color-primary-hover); }
.lg-linkbtn:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- reset-page waiting state (shared) -------------------------------- */
.lg-waiting { display: flex; flex-direction: column; align-items: center;
  gap: var(--ax-space-200); text-align: center; }
.lg-waiting__spinner { inline-size: 36px; block-size: 36px; border-radius: var(--ax-radius-full);
  border: 3px solid var(--ax-color-border);
  border-block-start-color: var(--ax-color-primary);
  animation: lg-spin 0.9s linear infinite; }
@keyframes lg-spin { to { transform: rotate(360deg); } }

/* ---- footer ------------------------------------------------------------ */
.lg-foot { display: flex; flex-wrap: wrap; align-items: center; gap: var(--ax-space-200);
  padding: var(--ax-space-250) clamp(20px, 4vw, 48px);
  border-block-start: 1px solid var(--ax-color-border);
  font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }
.lg-foot__item { display: inline-flex; align-items: center; gap: var(--ax-space-100); }
.lg-foot__item svg { color: var(--ax-color-success); }
.lg-foot__copy { margin-inline-start: auto; }

import { redirect } from "next/navigation";

// Sponsor instruction 2026-07-12: one login page only. The public landing
// (SCR-PUB-000) is retired; the root now routes straight to the unified
// Saqeel sign-in (SCR-PUB-010 v2). Signed-in users are bounced onward by
// /login → /launch role routing, so no session check is needed here.
export default function Root() {
  redirect("/login");
}

