import { chromium } from "@playwright/test";
const out = process.argv[2];
const B = "http://127.0.0.1:3000";
const browser = await chromium.launch();

async function shot(page, name) { await page.screenshot({ path: `${out}/${name}.png` }); }

// dark EN
let ctx = await browser.newContext({ viewport: { width: 1440, height: 860 }, colorScheme: "dark" });
let page = await ctx.newPage();
await page.goto(`${B}/locale?set=en`, { waitUntil: "networkidle" }).catch(()=>{});
await page.goto(`${B}/login`, { waitUntil: "networkidle" });
await page.evaluate(() => { localStorage.setItem("saqeel-theme","dark"); document.documentElement.setAttribute("data-theme","dark"); });
await page.reload({ waitUntil: "networkidle" });
await shot(page, "v3_dark_en");
// light EN (toggle)
await page.evaluate(() => { localStorage.setItem("saqeel-theme","light"); document.documentElement.setAttribute("data-theme","light"); });
await page.reload({ waitUntil: "networkidle" });
await shot(page, "v3_light_en");
await ctx.close();

// light AR
ctx = await browser.newContext({ viewport: { width: 1440, height: 860 } });
page = await ctx.newPage();
await page.goto(`${B}/locale?set=ar`, { waitUntil: "networkidle" }).catch(()=>{});
await page.goto(`${B}/login`, { waitUntil: "networkidle" });
await page.evaluate(() => { localStorage.setItem("saqeel-theme","light"); document.documentElement.setAttribute("data-theme","light"); });
await page.reload({ waitUntil: "networkidle" });
await shot(page, "v3_light_ar");
// dark AR
await page.evaluate(() => { localStorage.setItem("saqeel-theme","dark"); document.documentElement.setAttribute("data-theme","dark"); });
await page.reload({ waitUntil: "networkidle" });
await shot(page, "v3_dark_ar");

// sign in, app page in light
await page.evaluate(() => { localStorage.setItem("saqeel-theme","light"); document.documentElement.setAttribute("data-theme","light"); });
await page.goto(`${B}/locale?set=en`, { waitUntil: "networkidle" }).catch(()=>{});
await page.goto(`${B}/login`, { waitUntil: "networkidle" });
await page.locator("#email").fill("planner@mim.example");
await page.locator("#pw").fill("MimPlan!2026");
await page.locator("form:has(#email) button.ax-btn--prominent").click();
await page.waitForURL(u => u.pathname.startsWith("/planning"), { timeout: 20000 });
await page.waitForLoadState("networkidle");
await page.evaluate(() => { localStorage.setItem("saqeel-theme","light"); document.documentElement.setAttribute("data-theme","light"); });
await page.goto(`${B}/visits`, { waitUntil: "networkidle" });
await shot(page, "v3_visits_light");
await ctx.close();
await browser.close();
console.log("done");

