  executing: string;
  completed: string;
  legendTitle: string;
  high: string;
  medium: string;
  low: string;
  inspector: string;
  projected: string;
};

export default function LiveOps({ factories, regions, inspectors, strings: s }: {
  factories: LiveFactory[];
  regions: LiveRegion[];
  inspectors: LiveInspector[];
  strings: LiveOpsStrings;
}) {
  const Map = useMemo(() => dynamic(() => import("./LiveMapInner"), {
