/* ============================================================================
   SAQEEL — UNIFIED SIGN-IN (SCR-PUB-010 v4 · Login.dc.html Turn 4)
   "The inspection story": a solid credential panel on the start side (lockup,
   one form, trust footer — no text ever sits on imagery) beside a story
   panel — framed KSA map telling one sample inspection journey, plus the
   Plan → Inspect → Review → Decide strip. Works in both themes (tokens only —
   no raw values outside tokens.css).
   Shared with /reset: .lg-page (base), .lg-topbar, .lg-center, .lg-card,
   .lg-credentials, .lg-pwwrap, .lg-pwtoggle, .lg-submit, .lg-waiting.
   ========================================================================== */

.lg-page { min-block-size: 100dvh; display: flex; flex-direction: column;
  background: var(--ax-color-canvas);
  color: var(--ax-color-text); font: var(--ax-text-body); }

/* Split variant (login): fixed credential column on the start side, story
   panel takes the rest. The story panel disappears on small screens. */
.lg-page--split { display: grid; grid-template-columns: minmax(420px, 500px) minmax(0, 1fr); }
@media (max-width: 960px) { .lg-page--split { grid-template-columns: 1fr; } }

/* ---- credential panel -------------------------------------------------- */
.lg-panel { display: flex; flex-direction: column; min-inline-size: 0;
  min-block-size: 100dvh;
  padding: var(--ax-space-400) clamp(24px, 3vw, 44px);
  background: var(--ax-color-surface);
  border-inline-end: 1px solid var(--ax-color-border); }
@media (max-width: 960px) { .lg-panel { border-inline-end: none; } }

.lg-lockup { display: flex; align-items: center; gap: var(--ax-space-150); }
.lg-lockup__mark { inline-size: 36px; block-size: 36px; color: var(--ax-color-primary-hover); flex-shrink: 0; }
.lg-lockup__wordmark { font: 700 24px/1.2 var(--ax-font-arabic); color: var(--ax-color-text); }

.lg-controls { display: inline-flex; align-items: center; gap: var(--ax-space-100); }
/* theme toggle in the lockup row exists for small screens only — on desktop
   the story panel header owns it */
.lg-controls--compact { display: none; margin-inline-start: auto; }
@media (max-width: 960px) { .lg-controls--compact { display: inline-flex; } }

.lg-iconbtn { display: grid; place-items: center; inline-size: 40px; block-size: 40px;
  border: 1px solid var(--ax-color-border); border-radius: var(--ax-radius-full);
  background: var(--ax-color-surface); color: var(--ax-color-text-secondary); cursor: pointer;
  transition: color var(--ax-motion-fast), border-color var(--ax-motion-fast); }
.lg-iconbtn:hover { color: var(--ax-color-text); border-color: var(--ax-color-primary); }
.lg-iconbtn:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }

.lg-center { flex: 1; display: flex; flex-direction: column; justify-content: center;
  padding-block: var(--ax-space-300); }

.lg-card { inline-size: 100%; display: flex; flex-direction: column;
  gap: var(--ax-space-250); }
.lg-card__title { margin: 0; font: var(--ax-text-title); color: var(--ax-color-text); }
.lg-card__sub { margin: 0; margin-block-start: calc(-1 * var(--ax-space-150));
  font: var(--ax-text-body); color: var(--ax-color-text-secondary); }

/* ---- credential form ---------------------------------------------------- */
.lg-credentials { display: flex; flex-direction: column; gap: var(--ax-space-200); }
/* email addresses are LTR data even on the Arabic page */
.lg-input--email { text-align: start; direction: ltr; }
[dir="rtl"] .lg-input--email { text-align: left; }
.lg-pwwrap { position: relative; }
.lg-pwwrap .ax-input { padding-inline-end: 48px; }
.lg-pwtoggle { position: absolute; inset-block-start: 50%; inset-inline-end: var(--ax-space-100);
  transform: translateY(-50%); display: grid; place-items: center;
  inline-size: 36px; block-size: 36px; border: none; border-radius: var(--ax-radius-small);
  background: none; color: var(--ax-color-text-secondary); cursor: pointer; }
.lg-pwtoggle:hover { color: var(--ax-color-text); background: var(--ax-color-neutral-tint); }
.lg-submit { inline-size: 100%; margin-block-start: var(--ax-space-050); }
.lg-linkbtn { align-self: center; background: none; border: none; padding: 0; cursor: pointer;
  font: var(--ax-text-body-strong); color: var(--ax-color-primary-hover); }
.lg-linkbtn:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- reset page (shared) ------------------------------------------------ */
.lg-topbar { display: flex; align-items: center; justify-content: space-between;
  padding: var(--ax-space-250) clamp(20px, 4vw, 48px); }
.lg-topbar__brand { font: 700 20px/28px var(--ax-font-arabic); color: var(--ax-color-text); }
/* reset renders .lg-center inside the flat .lg-page (no panel): center the card */
.lg-page:not(.lg-page--split) .lg-center { display: grid; place-items: center;
  padding: var(--ax-space-300) clamp(20px, 4vw, 48px); }
.lg-page:not(.lg-page--split) .lg-card { inline-size: min(100%, 400px); }

.lg-waiting { display: flex; flex-direction: column; align-items: center;
  gap: var(--ax-space-200); text-align: center; }
.lg-waiting__spinner { inline-size: 36px; block-size: 36px; border-radius: var(--ax-radius-full);
  border: 3px solid var(--ax-color-border);
  border-block-start-color: var(--ax-color-primary);
  animation: lg-spin 0.9s linear infinite; }
@keyframes lg-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .lg-waiting__spinner { animation-duration: 2.4s; } }

/* ---- credential-panel footer -------------------------------------------- */
.lg-foot { display: flex; flex-direction: column; gap: var(--ax-space-100);
  padding-block-start: var(--ax-space-200);
  border-block-start: 1px solid var(--ax-color-border);
  font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }
.lg-foot__item { display: inline-flex; align-items: center; gap: var(--ax-space-100); }
.lg-foot__item svg { color: var(--ax-color-success); flex-shrink: 0; }
.lg-foot__row { display: flex; align-items: center; justify-content: space-between;
  gap: var(--ax-space-150); }
.lg-foot__copy { color: var(--ax-color-text-disabled); }
.lg-lang { font: 600 14px/20px var(--ax-font-sans); color: var(--ax-color-primary-hover);
  text-decoration: none; }
.lg-lang:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- demo-access helper (evaluation only) ------------------------------- */
.lg-demo { margin-block-start: var(--ax-space-100);
  padding-block-start: var(--ax-space-150);
  border-block-start: 1px solid var(--ax-color-border); }
.lg-demo__toggle { display: inline-flex; align-items: center; gap: var(--ax-space-050);
  background: none; border: none; padding: 0; cursor: pointer;
  font: var(--ax-text-caption); font-weight: 600; color: var(--ax-color-text-secondary); }
.lg-demo__toggle:hover { color: var(--ax-color-text); }
.lg-demo__chev { transition: transform var(--ax-motion-fast); }
.lg-demo__chev--open { transform: rotate(180deg); }
.lg-demo__body { margin-block-start: var(--ax-space-150); }
.lg-demo__hint { font: var(--ax-text-caption); color: var(--ax-color-text-secondary);
  margin-block-end: var(--ax-space-150); }
.lg-demo__list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--ax-space-100); }
.lg-demo__item { inline-size: 100%; display: grid; grid-template-columns: auto 1fr; column-gap: var(--ax-space-150);
  align-items: baseline; padding: var(--ax-space-100) var(--ax-space-150); text-align: start; cursor: pointer;
  background: var(--ax-color-surface-sunken); border: 1px solid var(--ax-color-border); border-radius: var(--ax-radius-small);
  transition: border-color var(--ax-motion-fast); }
.lg-demo__item:hover { border-color: var(--ax-color-primary); }
.lg-demo__item:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }
.lg-demo__role { font: var(--ax-text-body-strong); color: var(--ax-color-text); }
.lg-demo__dest { justify-self: end; font: var(--ax-text-caption); color: var(--ax-color-primary-hover); }
.lg-demo__email { grid-column: 1 / -1; font: 400 13px var(--ax-font-mono);
  color: var(--ax-color-text-secondary); direction: ltr; text-align: start; }
[dir="rtl"] .lg-demo__email { text-align: right; }

/* ============================================================================
   STORY PANEL — header · framed map · storyline strip
   ========================================================================== */
.lg-story { display: flex; flex-direction: column; gap: var(--ax-space-150);
  min-inline-size: 0; min-block-size: 100dvh; padding: clamp(20px, 2vw, 28px); }
@media (max-width: 960px) { .lg-story { display: none; } }

.lg-story__head { display: flex; align-items: center; justify-content: space-between;
  gap: var(--ax-space-200); }
.lg-story__heading { display: flex; flex-direction: column; gap: 3px; min-inline-size: 0; }
.lg-story__title { font: 700 17px/24px var(--ax-font-sans); color: var(--ax-color-text); }
.lg-story__overline { font: 600 10px/14px var(--ax-font-mono); letter-spacing: 0.16em;
