.lg-story__strip { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--ax-space-150); }
@media (max-width: 1280px) { .lg-story__strip { grid-template-columns: repeat(2, 1fr); } }
.lg-story__step { display: flex; flex-direction: column; gap: var(--ax-space-100);
  padding: var(--ax-space-200); background: var(--ax-color-surface);
  border: 1px solid var(--ax-color-border); border-radius: var(--ax-radius-standard); }
.lg-story__step-head { display: flex; align-items: center; gap: var(--ax-space-100); }
.lg-story__step-badge { display: grid; place-items: center; inline-size: 26px; block-size: 26px;
  border-radius: var(--ax-radius-small); background: var(--ax-color-primary);
  color: var(--ax-color-inverse-text); font: 700 12px var(--ax-font-mono); }
.lg-story__step-title { font: 700 15px/20px var(--ax-font-sans); color: var(--ax-color-text); }
.lg-story__step-body { margin: 0; font: 400 13px/21px var(--ax-font-sans);
  color: var(--ax-color-text-secondary); }

/* ---- the map itself ------------------------------------------------------ */
.lg-map { position: absolute; inset: 0; background: var(--ax-color-canvas); }
.lg-map .leaflet-container { background: transparent; font: inherit; }
/* CARTO dark tiles are too dim behind the mask — brighten them (design 4a) */
.lg-map .lg-map__tiles--bright { filter: brightness(2.3) saturate(1.2) contrast(1.02); }
.lg-map .leaflet-control-attribution { background: transparent;
  font: 400 9px var(--ax-font-sans); color: var(--ax-color-text-disabled); }
.lg-map .leaflet-control-attribution a { color: var(--ax-color-text-secondary); }

/* factory chip */
.lg-map__site { transform: translate(-50%, -50%); display: grid; place-items: center;
  border-radius: var(--ax-radius-small); background: var(--ax-color-surface);
  border: 1.5px solid var(--ax-color-primary); box-shadow: var(--ax-shadow-raised);
  color: var(--ax-color-primary-hover); }
.lg-map__sitelabel { white-space: nowrap; color: var(--ax-color-text);
  text-shadow: 0 1px 4px var(--ax-color-canvas); }
.lg-map__sitelabel--en { font: 600 10px var(--ax-font-mono); letter-spacing: 2px; }
.lg-map__sitelabel--ar { font: 700 13px var(--ax-font-arabic); }

/* animated route (plan -> arrival) */
.lg-map__route { animation: lg-map-route 24s linear infinite; }
@keyframes lg-map-route { to { stroke-dashoffset: -320; } }

/* inspector en route — pulsing emerald */
.lg-map__insp { transform: translate(-50%, -50%); position: relative; }
.lg-map__insp-ping { position: absolute; inset: -7px; border-radius: var(--ax-radius-full);
  border: 1.5px solid var(--ax-color-success); opacity: 0.7;
  animation: lg-map-ping 2.4s ease-out infinite; }
@keyframes lg-map-ping { 0% { transform: scale(0.5); opacity: 0.8; } 100% { transform: scale(2); opacity: 0; } }
.lg-map__insp-dot { display: grid; place-items: center; inline-size: 22px; block-size: 22px;
  border-radius: var(--ax-radius-full); background: var(--ax-color-success);
  border: 2px solid var(--ax-color-canvas); box-shadow: var(--ax-shadow-raised);
  color: var(--ax-color-inverse-text); }

/* step badges on the map (01 planned · 02 geofenced arrival) */
.lg-map__badge { transform: translate(-50%, -68px); display: grid; place-items: center;
  inline-size: 24px; block-size: 24px; border-radius: var(--ax-radius-full);
  background: var(--ax-color-primary); color: var(--ax-color-inverse-text);
  font: 700 11px var(--ax-font-mono); box-shadow: var(--ax-shadow-raised); }

@media (prefers-reduced-motion: reduce) {
  .lg-map__route { animation: none; }
  .lg-map__insp-ping { animation: none; opacity: 0.35; }
}

/* ---- static fallback illustration (SaqeelHero) --------------------------- */
.lg-hero { inline-size: 100%; block-size: 100%; }
.lg-hero__fence { animation: lg-fence 60s linear infinite; transform-box: fill-box; transform-origin: center; }
@keyframes lg-fence { to { stroke-dashoffset: -220; } }
.lg-hero__pulse { transform-box: fill-box; transform-origin: center; opacity: 0;
  animation: lg-pulsering 3.2s ease-out infinite; }
@keyframes lg-pulsering { 0% { transform: scale(0.5); opacity: 0.5; } 100% { transform: scale(1.7); opacity: 0; } }
.lg-hero__ping { transform-box: fill-box; transform-origin: center; opacity: 0.28;
  animation: lg-ping 2.6s ease-out infinite; }
@keyframes lg-ping { 0% { transform: scale(0.4); opacity: 0.5; } 100% { transform: scale(1.5); opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .lg-hero__fence, .lg-hero__pulse, .lg-hero__ping { animation: none; }
}

