tool_input.content:
// CD-001 V7 Atlas — verified anchor + sample-journey data (Layer 1 truth base).
// Every coordinate is a PUBLIC industrial-city or civic-orientation location
// from the MODON / RCJY register (SAUDI_ATLAS_REFERENCE_REGISTER_CD001.csv).
// NOTHING here is a customer factory or an operational metric — the six
// lifecycle states and per-node "sample state" are ILLUSTRATIVE only
// (CD001_RUNTIME_ATLAS_CONTRACT Layer 5 / FORBIDDEN list). Labels are carried
// EN/AR inline because these are sample geographic captions, not localizable
// ui_strings owned by the localization module.

export type Bi = { en: string; ar: string };

// Halo tone → token (Layer 3 palette; NO red on the public surface):
//   arrival = success (green) · planned = warning (amber)
//   virtual = info (cyan)     · route/decision = primary (violet)
export type HaloTone = "arrival" | "planned" | "virtual" | "route";

// Original transparent-structure glyphs (flat Layer-2 fallback shipped in the
// reserved slots until the design-owned WebP renders land — see asset register,
// production_status = DESIGN CONCEPT — PENDING).
export type StructGlyph =
  | "process" | "refining" | "metals" | "pharma" | "fabrication"
  | "packaging" | "food" | "mfg" | "logistics";

export type AtlasNode = {
  id: string;
  lat: number;
  lng: number;
  name: Bi;
  industry: Bi;
  sampleState: Bi; // illustrative lifecycle caption only
  halo: HaloTone;
  glyph: StructGlyph;
  // Intended production asset (ATL3D-*, WebP+AVIF, transparent, fixed dims).
  // Absent today → <img> onerror degrades to the flat glyph in the same slot
  // (no layout shift; the documented image-failure mode).
  asset: { src: string; w: number; h: number };
  orientationAnchor?: boolean; // Riyadh carries the Kingdom Centre silhouette
};

const A = "/brand/saudi-atlas";

// Nine verified public industrial cities (MODON / RCJY). Positions only —
// never risk, compliance, overdue, workload or inspector data.
export const NODES: AtlasNode[] = [
  { id: "jubail", lat: 27.00, lng: 49.66, halo: "arrival", glyph: "process",
    name: { en: "JUBAIL", ar: "الجبيل" },
    industry: { en: "Petrochemical / process", ar: "بتروكيماويات ومعالجة" },
    sampleState: { en: "Sample arrival confirmed", ar: "وصول تجريبي مؤكَّد" },
    asset: { src: `${A}/jubail-process.webp`, w: 320, h: 240 } },
  { id: "riyadh", lat: 24.63, lng: 46.85, halo: "planned", glyph: "pharma", orientationAnchor: true,
    name: { en: "RIYADH", ar: "الرياض" },
    industry: { en: "Pharma / clean assembly", ar: "أدوية وتجميع نظيف" },
    sampleState: { en: "Sample visit planned", ar: "زيارة تجريبية مخطَّطة" },
    asset: { src: `${A}/riyadh-pharma.webp`, w: 280, h: 210 } },
  { id: "yanbu", lat: 24.02, lng: 38.19, halo: "arrival", glyph: "refining",
    name: { en: "YANBU", ar: "ينبع" },
    industry: { en: "Refining / port-linked", ar: "تكرير ومرتبط بالميناء" },
    sampleState: { en: "Sample inspection underway", ar: "تفتيش تجريبي جارٍ" },
    asset: { src: `${A}/yanbu-refining.webp`, w: 280, h: 210 } },
  { id: "ras-al-khair", lat: 27.52, lng: 49.20, halo: "route", glyph: "metals",
    name: { en: "RAS AL-KHAIR", ar: "رأس الخير" },
    industry: { en: "Mining / metals", ar: "تعدين ومعادن" },
    sampleState: { en: "Sample review stage", ar: "مرحلة مراجعة تجريبية" },
    asset: { src: `${A}/rak-metals.webp`, w: 280, h: 210 } },
  { id: "dammam", lat: 26.35, lng: 49.98, halo: "planned", glyph: "fabrication",
    name: { en: "DAMMAM", ar: "الدمام" },
    industry: { en: "Fabrication / heavy mfg", ar: "تصنيع ثقيل" },
    sampleState: { en: "Sample visit planned", ar: "زيارة تجريبية مخطَّطة" },
    asset: { src: `${A}/dammam-fabrication.webp`, w: 260, h: 200 } },
  { id: "jeddah", lat: 21.36, lng: 39.27, halo: "virtual", glyph: "packaging",
    name: { en: "JEDDAH", ar: "جدة" },
    industry: { en: "Food / packaging", ar: "أغذية وتعبئة" },
    sampleState: { en: "Sample virtual inspection", ar: "تفتيش افتراضي تجريبي" },
    asset: { src: `${A}/jeddah-food.webp`, w: 280, h: 210 } },
  { id: "qassim", lat: 26.30, lng: 43.77, halo: "planned", glyph: "food",
    name: { en: "QASSIM", ar: "القصيم" },
    industry: { en: "Food production", ar: "إنتاج غذائي" },
    sampleState: { en: "Sample visit planned", ar: "زيارة تجريبية مخطَّطة" },
    asset: { src: `${A}/qassim-food.webp`, w: 240, h: 180 } },
  { id: "hail", lat: 27.44, lng: 41.69, halo: "planned", glyph: "mfg",
    name: { en: "HA'IL", ar: "حائل" },
    industry: { en: "Regional manufacturing", ar: "تصنيع إقليمي" },
    sampleState: { en: "Sample visit planned", ar: "زيارة تجريبية مخطَّطة" },
    asset: { src: `${A}/hail-mfg.webp`, w: 220, h: 170 } },
  { id: "jazan", lat: 16.89, lng: 42.62, halo: "route", glyph: "logistics",
    name: { en: "JAZAN", ar: "جازان" },
    industry: { en: "Downstream / logistics", ar: "صناعات تحويلية ولوجستيات" },
    sampleState: { en: "Sample transit stage", ar: "مرحلة نقل تجريبية" },
    asset: { src: `${A}/jazan-logistics.webp`, w: 240, h: 180 } },
];

// Civic orientation labels (non-industrial reference points, spread for
// spatial context). No religious landmarks (contract Layer-5 reject list).
export const ORIENTATION_CITIES: { lat: number; lng: number; name: Bi }[] = [
  { lat: 28.38, lng: 36.57, name: { en: "Tabuk", ar: "تبوك" } },
  { lat: 29.97, lng: 40.21, name: { en: "Sakaka", ar: "سكاكا" } },
  { lat: 18.22, lng: 42.51, name: { en: "Abha", ar: "أبها" } },
  { lat: 17.49, lng: 44.13, name: { en: "Najran", ar: "نجران" } },
];

// The single illustrative journey the 14s loop tells: PLAN in Riyadh →
// TRAVEL the dashed route → ARRIVE at the Jubail geofence → INSPECT → REVIEW →
// DECIDE. Reused from the accepted V4 story path.
export const JOURNEY = {
  plan: [24.63, 46.85] as [number, number],
  route: [[24.63, 46.85], [25.35, 47.75], [26.25, 48.85], [27.00, 49.66]] as [number, number][],
  inspector: [26.25, 48.85] as [number, number],
  arrive: [27.00, 49.66] as [number, number],
  geofenceRadiusM: 42000,
};

// Six illustrative lifecycle stages driving the overlays / tablist.
export const STAGE_ORDER = ["plan", "travel", "arrive", "inspect", "review", "decide"] as const;
export type AtlasStageId = (typeof STAGE_ORDER)[number];

export function haloToken(t: HaloTone): string {
  switch (t) {
    case "arrival": return "--ax-color-success";
    case "planned": return "--ax-color-warning";
    case "virtual": return "--ax-color-info";
    case "route": return "--ax-color-primary";
  }
}

// CD-001 V7 Atlas — 14s illustrative motion timeline (MOTION_STORYBOARD_CD001).
// A single rAF loop that advances the six lifecycle stages on a calm cadence
// and hands the active index back to the caller. It NEVER runs when the user
// prefers reduced motion, and it pauses while a dossier is open, while any
// atlas element holds focus, or while the tab is hidden (document.hidden).
// No whole-map pulsing, particles or flashing — the visual restraint lives in
// the components; this file only owns time.

import { STAGE_ORDER } from "./saudi-atlas-locations";

// Cumulative stage end times (seconds) from the storyboard.
//   plan 0–2.5 · travel 2.5–5 · arrive 5–7 · inspect 7–9.5 · review 9.5–12 · decide 12–14
const STAGE_END_S = [2.5, 5.0, 7.0, 9.5, 12.0, 14.0];
const LOOP_MS = STAGE_END_S[STAGE_END_S.length - 1] * 1000;

export function prefersReducedMotion(): boolean {
  return typeof window !== "undefined"
    && !!window.matchMedia
    && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function stageIndexAt(ms: number): number {
  const t = (ms % LOOP_MS) / 1000;
  for (let i = 0; i < STAGE_END_S.length; i++) if (t < STAGE_END_S[i]) return i;
  return STAGE_ORDER.length - 1;
}

export type AtlasTimeline = {
  start: () => void;
  stop: () => void;
  pause: () => void;
  resume: () => void;
};

// onStage is called only when the active stage index changes.
export function createAtlasTimeline(onStage: (index: number) => void): AtlasTimeline {
  let raf = 0;
  let running = false;
  let paused = false;
  let last = 0;            // timestamp of the previous frame
  let elapsed = 0;         // accumulated, pause-aware playback time (ms)
  let current = -1;

  function frame(now: number) {
    if (!running) return;
    if (!paused) {
      if (last) elapsed += now - last;
      const idx = stageIndexAt(elapsed);
      if (idx !== current) { current = idx; onStage(idx); }
    }
    last = now;
    raf = requestAnimationFrame(frame);
  }

  function onVisibility() {
    if (document.hidden) paused = true;
    else { last = 0; paused = false; }
  }

  return {
    start() {
      if (running || prefersReducedMotion()) return;
      running = true; paused = false; last = 0; elapsed = 0; current = -1;
      document.addEventListener("visibilitychange", onVisibility);
      onStage(0);
      raf = requestAnimationFrame(frame);
    },
    stop() {
      running = false;
      cancelAnimationFrame(raf);
      document.removeEventListener("visibilitychange", onVisibility);
    },
    pause() { paused = true; },
    resume() { if (running && !document.hidden) { last = 0; paused = false; } },
  };
}

"use client";
// CD-001 V7 Atlas — LAYER 1 (authoritative real map). This component owns the
// Leaflet lifecycle only: a theme-aware labelled CARTO basemap, the bundled
// KSA boundary (public/geo/sau.geo.json — no third-party GeoJSON host), a
// frame mask, civic orientation labels and always-visible attribution. It does
// NOT draw factories, routes, halos or actors — those are Layers 2–4, owned by
// SaudiIndustrialAtlas, which receives the live map instance through onReady.
// The credential form renders and works before/during/after this map loads;
// the atlas frame has fixed dimensions so there is no layout shift. Colours
// resolve from ax base tokens (GLOBAL COLOR LAW) which are literal hex in
// tokens.css and therefore safe to hand to Leaflet's SVG renderer.
import { useEffect, useRef } from "react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import { ORIENTATION_CITIES } from "./saudi-atlas-locations";

// KSA framing bounds (also the SVGOverlay anchor for the Layer-2 terrain slab).
export const ATLAS_BOUNDS: L.LatLngBoundsExpression = [[15.8, 34.4], [32.4, 56.0]];
// Painted over everything outside the KSA rings (fillRule evenodd).
const MASK_OUTER: [number, number][] = [[-89, -300], [-89, 300], [89, 300], [89, -300]];

export type AtlasTokens = {
  canvas: string; primary: string; success: string; warning: string; info: string; text: string;
};

// The context the Layer 2–4 owner needs to draw over this map.
export type AtlasMapContext = { map: L.Map; rings: [number, number][][]; dark: boolean; tokens: AtlasTokens };

export function isDark(): boolean {
  const attr = document.documentElement.getAttribute("data-theme");
  if (attr === "light") return false;
  if (attr === "dark") return true;
  return !window.matchMedia?.("(prefers-color-scheme: light)").matches;
}

// Base tokens are literal hex in tokens.css, so :root computed values are safe
// for Leaflet's SVG renderer (derived color-mix tokens are not).
export function atlasTokens(): AtlasTokens {
  const cs = getComputedStyle(document.documentElement);
  const g = (v: string) => cs.getPropertyValue(v).trim();
  return {
    canvas: g("--ax-color-canvas"), primary: g("--ax-color-primary"),
    success: g("--ax-color-success"), warning: g("--ax-color-warning"),
    info: g("--ax-color-info"), text: g("--ax-color-text"),
  };
}

export default function StoryMapInner({ locale, onReady, onFail }: {
  locale: "ar" | "en";
  onReady: (ctx: AtlasMapContext) => void;
  onFail: () => void;
}) {
  const elRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<L.Map | null>(null);
  const ringsRef = useRef<[number, number][][] | null>(null);

  useEffect(() => {
    let disposed = false;

    async function loadRings(): Promise<[number, number][][]> {
      if (ringsRef.current) return ringsRef.current;
      const res = await fetch("/geo/sau.geo.json");
      if (!res.ok) throw new Error(`sau.geo.json ${res.status}`);
      const gj = await res.json();
      const geom = gj.features ? gj.features[0].geometry : (gj.geometry ?? gj);
      const polys: [number, number][][][] = geom.type === "Polygon" ? [geom.coordinates] : geom.coordinates;
      const rings = polys.map(p => p[0].map(([lng, lat]: [number, number]) => [lat, lng] as [number, number]));
      if (!rings.length) throw new Error("empty boundary");
      ringsRef.current = rings;
      return rings;
    }

    function destroy() { mapRef.current?.remove(); mapRef.current = null; }

    async function init() {
      const el = elRef.current;
      if (!el || disposed) return;
      destroy();
      const rings = await loadRings();
      if (disposed) return;
      const dark = isDark();
      const tokens = atlasTokens();

      const map = L.map(el, {
        zoomControl: false, dragging: false, scrollWheelZoom: false, doubleClickZoom: false,
        boxZoom: false, keyboard: false, touchZoom: false, attributionControl: true, zoomSnap: 0.05,
      });
      mapRef.current = map;

      L.tileLayer(`https://{s}.basemaps.cartocdn.com/${dark ? "dark_all" : "light_all"}/{z}/{x}/{y}.png`, {
        subdomains: "abcd", className: dark ? "lg-map__tiles--bright" : "",
        attribution: '&copy; <a href="https://carto.com/">CARTO</a> · <a href="https://www.openstreetmap.org/copyright">OSM</a>',
      }).addTo(map);
      map.fitBounds(ATLAS_BOUNDS, { paddingTopLeft: [20, 24], paddingBottomRight: [20, 30] });

      // Frame mask: everything outside the real boundary painted with the canvas.
      L.polygon([MASK_OUTER, ...rings], {
        stroke: false, fillColor: tokens.canvas, fillOpacity: 1, fillRule: "evenodd", interactive: false, pane: "tilePane",
      }).addTo(map);
      rings.forEach(r => L.polyline([...r, r[0]], {
        color: tokens.primary, weight: 1.5, opacity: 0.75, interactive: false,
      }).addTo(map));

      // Civic orientation labels (Layer 1 context; non-industrial, no metrics).
      ORIENTATION_CITIES.forEach(c => {
        L.marker([c.lat, c.lng], {
          icon: L.divIcon({
            className: "",
            html: `<div class="lg-atlas3d__orient lg-atlas3d__orient--${locale}">${c.name[locale]}</div>`,
            iconSize: [0, 0],
          }),
          interactive: false, keyboard: false,
        }).addTo(map);
      });

      onReady({ map, rings, dark, tokens });
    }

    init().catch(() => { if (!disposed) onFail(); });

    // Theme flip re-inits Layer 1; onReady fires again so the atlas rebuilds.
    const obs = new MutationObserver(() => { init().catch(() => { if (!disposed) onFail(); }); });
    obs.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

    return () => { disposed = true; obs.disconnect(); destroy(); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return <div ref={elRef} className="lg-map" dir="ltr" aria-hidden="true" />;
}

"use client";
// CD-001 V7 Atlas — dossier (Layer 4). One at a time, hover/focus opens it and
// click/tap locks it (role=dialog when locked, with a close control that
// returns focus to the marker). The SAMPLE line is mandatory and never
// tooltip-hidden. Layout variant is driven purely by CSS from the frame size:
// floating card (desktop) → side panel (landscape) → bottom sheet (portrait).
import { useEffect, useRef } from "react";
import type { AtlasNode } from "./saudi-atlas-locations";
import { haloToken } from "./saudi-atlas-locations";

export type DossierStrings = {
  sample: string;   // persistent SAMPLE disclosure line
  industry: string; // field label
  state: string;    // field label
  close: string;    // close button aria-label
};

export default function SaudiAtlasDossier({ node, locked, locale, strings: t, onClose }: {
  node: AtlasNode | null;
  locked: boolean;
  locale: "ar" | "en";
  strings: DossierStrings;
  onClose: () => void;
}) {
  const closeRef = useRef<HTMLButtonElement | null>(null);

  // When it locks, move focus to the close control so Esc/Tab are captured.
  useEffect(() => { if (locked) closeRef.current?.focus(); }, [locked, node?.id]);

  if (!node) return null;
  const tone = `var(${haloToken(node.halo)})`;

  return (
    <div
      className={`lg-atlas3d__dossier${locked ? " lg-atlas3d__dossier--locked" : ""}`}
      role={locked ? "dialog" : "group"}
      aria-modal={undefined}
      aria-label={`${node.name[locale]} — ${node.industry[locale]}`}
      onKeyDown={e => { if (e.key === "Escape" && locked) { e.stopPropagation(); onClose(); } }}
    >
      <div className="lg-atlas3d__dossier-head">
        <span className="lg-atlas3d__dossier-dot" style={{ background: tone }} aria-hidden="true" />
        <span className="lg-atlas3d__dossier-name">{node.name[locale]}</span>
        {locked && (
          <button ref={closeRef} type="button" className="lg-atlas3d__dossier-close"
            aria-label={t.close} onClick={onClose}>✕</button>
        )}
      </div>
      <dl className="lg-atlas3d__dossier-body">
        <div className="lg-atlas3d__dossier-row">
          <dt>{t.industry}</dt><dd>{node.industry[locale]}</dd>
        </div>
        <div className="lg-atlas3d__dossier-row">
          <dt>{t.state}</dt>
          <dd><span className="lg-atlas3d__dossier-state" style={{ color: tone }}>{node.sampleState[locale]}</span></dd>
        </div>
      </dl>
      <p className="lg-atlas3d__dossier-sample">{t.sample}</p>
    </div>
  );
}

"use client";
// CD-001 V7 Atlas — LAYERS 2–4 over the real Layer-1 map (StoryMapInner).
//   L2  3D visual assets: terrain relief slab (inline SVG overlay) + per-node
//       structures. Structures try the design-owned WebP (asset register,
//       PRODUCTION ASSET PENDING) and degrade to an original flat glyph in the
//       SAME reserved slot on error — no layout shift, the documented failure
//       mode. Storytelling only; never authoritative.
//   L3  inspection overlays: tone halos, the sample route, geofence, actors,
//       evidence / review / decision cues — all ILLUSTRATIVE, no red states.
//   L4  interaction: markers are tabbable role=button; hover/focus opens a
//       dossier, click/tap locks it, Esc returns focus. One dossier at a time;
//       while one is open the caller pauses the motion loop.
// The 14s timeline + the six-stage tablist live in StoryPanel (single source
// of stage truth); this component renders whatever `activeStage` it is given.
import { useCallback, useEffect, useRef, useState } from "react";
import L from "leaflet";
import StoryMapInner, { ATLAS_BOUNDS, type AtlasMapContext } from "./StoryMapInner";
import {
  NODES, JOURNEY, STAGE_ORDER, haloToken,
  type AtlasNode, type AtlasStageId, type StructGlyph,
} from "./saudi-atlas-locations";
import SaudiAtlasDossier, { type DossierStrings } from "./SaudiAtlasDossier";

// Original flat structure glyphs (Layer-2 fallback in the reserved slots).
// currentColor so the tone comes from the node's halo class.
const GLYPH: Record<StructGlyph, string> = {
  process: '<path d="M4 40V22l7 4v-4l7 4V14l7 4V8h5v32Z"/><path d="M20 8h5" stroke-width="2"/>',
  refining: '<path d="M6 40V20h10v20Z"/><path d="M20 40V16h9v24Z"/><path d="M33 40V10l3-6 3 6v30Z"/>',
  metals: '<path d="M4 40V24h34v16Z"/><path d="M8 24l6-8h18l6 8" fill="none" stroke-width="2"/>',
  pharma: '<rect x="6" y="18" width="30" height="22" rx="2"/><path d="M6 18l15-8 15 8" fill="none" stroke-width="2"/>',
  fabrication: '<path d="M4 40V22l10 6V22l10 6V22l10 6v12Z"/>',
  packaging: '<rect x="6" y="20" width="14" height="20"/><rect x="22" y="14" width="16" height="26"/>',
  food: '<rect x="6" y="16" width="12" height="24" rx="1"/><rect x="20" y="16" width="12" height="24" rx="1"/>',
  mfg: '<path d="M6 40V24l8-6 8 6v16Z"/><rect x="26" y="22" width="10" height="18"/>',
  logistics: '<rect x="4" y="22" width="24" height="18"/><path d="M28 28h8l4 6v6H28Z"/>',
};

const INSPECTOR_SVG = '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><circle cx="12" cy="6" r="3.2"/><path d="M6 22v-5a6 6 0 0 1 12 0v5Z"/></svg>';
const VEHICLE_SVG = '<svg viewBox="0 0 24 24" width="18" height="12" fill="currentColor"><path d="M2 14V9l4-4h10l3 4h3v5Z"/><circle cx="7" cy="16" r="2"/><circle cx="17" cy="16" r="2"/></svg>';
const EVIDENCE_SVG = '<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M5 12l4 4 10-10"/></svg>';
const SEAL_SVG = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.4"><circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-6"/></svg>';

function nodeDisplaySize(n: AtlasNode): [number, number] {
  const w = Math.min(64, Math.round(n.asset.w / 5));
  const h = Math.round(w * (n.asset.h / n.asset.w));
  return [w, h];
}

// Linear projection of geo → the terrain SVG viewBox (overlay is stretched to
// ATLAS_BOUNDS with preserveAspectRatio=none, so the mapping stays exact).
function terrainSvg(rings: [number, number][][]): SVGSVGElement {
  const [[latMin, lngMin], [latMax, lngMax]] = ATLAS_BOUNDS as [[number, number], [number, number]];
  const VB = 1000;
  const px = (lng: number) => ((lng - lngMin) / (lngMax - lngMin)) * VB;
  const py = (lat: number) => ((latMax - lat) / (latMax - latMin)) * VB;
  const d = rings
    .map(r => "M" + r.map(([lat, lng]) => `${px(lng).toFixed(1)},${py(lat).toFixed(1)}`).join("L") + "Z")
    .join(" ");
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", `0 0 ${VB} ${VB}`);
  svg.setAttribute("preserveAspectRatio", "none");
  svg.setAttribute("class", "lg-atlas3d__terrain");
  svg.innerHTML =
    `<path class="lg-atlas3d__terrain-shadow" d="${d}"/>` +
    `<path class="lg-atlas3d__terrain-top" d="${d}"/>`;
  return svg;
}

type Journey = {
  route: L.Polyline;
  els: { vehicle: HTMLElement; inspector: HTMLElement; geofence: HTMLElement;
         evidence: HTMLElement[]; review: HTMLElement; seal: HTMLElement };
};

function divMarker(map: L.Map, at: L.LatLngExpression, html: string, cls = ""): L.Marker {
  const m = L.marker(at, { icon: L.divIcon({ className: cls, html, iconSize: [0, 0] }), interactive: false, keyboard: false });
  m.addTo(map);
  return m;
}

export default function SaudiIndustrialAtlas({
  locale, activeStage, dossierStrings, onInteractingChange, onFail,
}: {
  locale: "ar" | "en";
  activeStage: AtlasStageId;
  dossierStrings: DossierStrings;
  onInteractingChange: (interacting: boolean) => void;
  onFail: () => void;
}) {
  const [hover, setHover] = useState<AtlasNode | null>(null);
  const [locked, setLocked] = useState<AtlasNode | null>(null);
  const shown = locked ?? hover;

  const group = useRef<L.LayerGroup | null>(null);
  const journey = useRef<Journey | null>(null);
  const markerEls = useRef<Map<string, HTMLElement>>(new Map());
  const stageRef = useRef<AtlasStageId>(activeStage);
  stageRef.current = activeStage;

  // Report interaction (dossier open OR a marker holding hover/focus) so the
  // caller can pause the motion loop.
  useEffect(() => { onInteractingChange(shown !== null); }, [shown, onInteractingChange]);

  const closeLocked = useCallback(() => {
    const id = locked?.id;
    setLocked(null);
    if (id) requestAnimationFrame(() => markerEls.current.get(id)?.focus());
  }, [locked]);

  // Show/hide the journey overlays for a stage index (0..5).
  const applyStage = useCallback((stage: AtlasStageId) => {
    const j = journey.current; if (!j) return;
    const i = STAGE_ORDER.indexOf(stage);
    j.route.setStyle({ opacity: i >= 1 ? 0.9 : 0 });
    const on = (el: HTMLElement, cond: boolean) => el.classList.toggle("is-on", cond);
    on(j.els.vehicle, i >= 1 && i <= 2);
    const enteringArrive = i >= 2 && !j.els.geofence.classList.contains("is-on");
    on(j.els.geofence, i >= 2);
    if (enteringArrive) {
      j.els.geofence.classList.remove("pulse");
      // reflow so the one-shot pulse can replay on each arrival
      void j.els.geofence.offsetWidth;
      j.els.geofence.classList.add("pulse");
    }
    on(j.els.inspector, i >= 2);
    j.els.evidence.forEach(e => on(e, i >= 3));
    on(j.els.review, i >= 4);
    on(j.els.seal, i >= 5);
  }, []);

  const buildLayers = useCallback((ctx: AtlasMapContext) => {
    const { map, rings } = ctx;
    if (!group.current) group.current = L.layerGroup().addTo(map);
    else { group.current.clearLayers(); group.current.addTo(map); }
    const g = group.current;
    markerEls.current.clear();

    // L2 — terrain relief slab
    L.svgOverlay(terrainSvg(rings), ATLAS_BOUNDS, { interactive: false, opacity: 1 }).addTo(g);

    // L2/L4 — node structures (interactive)
    NODES.forEach(n => {
      const [w, h] = nodeDisplaySize(n);
      const html =
        `<div class="lg-atlas3d__node lg-atlas3d__node--${n.halo}" style="--nw:${w}px;--nh:${h}px">
           <span class="lg-atlas3d__halo" aria-hidden="true"></span>
           <span class="lg-atlas3d__struct" aria-hidden="true">
             <span class="lg-atlas3d__struct-flat"><svg viewBox="0 0 44 44" fill="currentColor" stroke="currentColor" stroke-linejoin="round">${GLYPH[n.glyph]}</svg></span>
             <img class="lg-atlas3d__struct-img" src="${n.asset.src}" width="${w}" height="${h}" alt="" loading="lazy"
                  onload="this.style.opacity=1" onerror="this.remove()"/>
             ${n.orientationAnchor ? '<span class="lg-atlas3d__anchor" aria-hidden="true"></span>' : ""}
           </span>
           <span class="lg-atlas3d__node-base" aria-hidden="true"></span>
           <span class="lg-atlas3d__node-label lg-atlas3d__node-label--${locale}">${n.name[locale]}</span>
         </div>`;
      const marker = L.marker([n.lat, n.lng], {
        icon: L.divIcon({ className: "", html, iconSize: [0, 0] }),
        interactive: true, keyboard: false, riseOnHover: true,
      }).addTo(g);

      const el = marker.getElement();
      if (!el) return;
      const inner = el.firstElementChild as HTMLElement;
      inner.tabIndex = 0;
      inner.setAttribute("role", "button");
      inner.setAttribute("aria-label",
        `${n.name[locale]}, ${n.industry[locale]}. ${n.sampleState[locale]}. ${dossierStrings.sample}`);
      markerEls.current.set(n.id, inner);

      const open = () => setHover(n);
      const clear = () => setHover(h => (h?.id === n.id ? null : h));
      inner.addEventListener("mouseenter", open);
      inner.addEventListener("mouseleave", clear);
      inner.addEventListener("focus", open);
      inner.addEventListener("blur", clear);
      inner.addEventListener("click", () => setLocked(n));
      inner.addEventListener("keydown", (e: KeyboardEvent) => {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setLocked(n); }
        if (e.key === "Escape") { setLocked(null); inner.blur(); }
      });
    });

    // L3 — the illustrative journey (Riyadh → Jubail)
    const route = L.polyline(JOURNEY.route, {
      className: "lg-atlas3d__route", color: `var(--ax-color-primary)`,
      weight: 2.5, opacity: 0, dashArray: "7 9", interactive: false,
    }).addTo(g);

    const vehicle = divMarker(g as unknown as L.Map, JOURNEY.inspector,
      `<span class="lg-atlas3d__vehicle">${VEHICLE_SVG}</span>`).getElement()!.firstElementChild as HTMLElement;
    const inspector = divMarker(g as unknown as L.Map, JOURNEY.arrive,
      `<span class="lg-atlas3d__actor">${INSPECTOR_SVG}</span>`).getElement()!.firstElementChild as HTMLElement;
    const geofence = divMarker(g as unknown as L.Map, JOURNEY.arrive,
      `<span class="lg-atlas3d__geofence" style="--fence-r:${Math.round(JOURNEY.geofenceRadiusM / 900)}px"></span>`).getElement()!.firstElementChild as HTMLElement;

    const ev = (dLat: number, dLng: number) => divMarker(g as unknown as L.Map,
      [JOURNEY.arrive[0] + dLat, JOURNEY.arrive[1] + dLng],
      `<span class="lg-atlas3d__evidence">${EVIDENCE_SVG}</span>`).getElement()!.firstElementChild as HTMLElement;
    const evidence = [ev(0.35, -0.35), ev(-0.3, 0.3)];

    const review = divMarker(g as unknown as L.Map, [JOURNEY.arrive[0] + 0.7, JOURNEY.arrive[1] - 0.9],
      `<span class="lg-atlas3d__cue lg-atlas3d__cue--review">v1 ✓</span>`).getElement()!.firstElementChild as HTMLElement;
    const seal = divMarker(g as unknown as L.Map, [JOURNEY.arrive[0] + 1.1, JOURNEY.arrive[1] - 0.2],
      `<span class="lg-atlas3d__cue lg-atlas3d__cue--seal">${SEAL_SVG}</span>`).getElement()!.firstElementChild as HTMLElement;

    journey.current = { route, els: { vehicle, inspector, geofence, evidence, review, seal } };
    applyStage(stageRef.current);
  }, [locale, dossierStrings.sample, applyStage]);

  // Rebuild overlays whenever Layer 1 (re)initialises — including theme flips,
  // which recreate the map instance.
  const onReady = useCallback((ctx: AtlasMapContext) => {
    setHover(null); setLocked(null);
    try { buildLayers(ctx); } catch { onFail(); }
  }, [buildLayers, onFail]);

  // Stage changes from the tablist / motion loop re-drive the overlays.
  useEffect(() => { applyStage(activeStage); }, [activeStage, applyStage]);

  return (
    <>
      <StoryMapInner locale={locale} onReady={onReady} onFail={onFail} />
      <SaudiAtlasDossier node={shown} locked={locked !== null} locale={locale}
        strings={dossierStrings} onClose={closeLocked} />
    </>
  );
}

