tool_input.content:
"use client";
// CD-001 V7 Atlas — story panel host. Owns the single source of stage truth
// (the six illustrative lifecycle stages) and the 14s motion loop, and lays out
// the persistent SAMPLE truth banner, the map/list toggle, the lifecycle
// tablist (roving tabindex) and the module strip. The premium 3D atlas
// (SaudiIndustrialAtlas) is dynamically imported (ssr:false) exactly like the
// old map; if Layer 1 cannot initialise (offline, tiles blocked, boundary
// missing) the static SaqeelHero SVG takes the frame instead. Motion is
// disabled under prefers-reduced-motion — the tablist becomes the only driver.
import { useCallback, useEffect, useRef, useState } from "react";
import dynamic from "next/dynamic";
import ThemeToggle from "@/components/ThemeToggle";
import SaqeelHero from "./SaqeelHero";
import { NODES, STAGE_ORDER, type AtlasStageId } from "./saudi-atlas-locations";
import { createAtlasTimeline, type AtlasTimeline } from "./saudi-atlas-motion";
import type { DossierStrings } from "./SaudiAtlasDossier";

const Atlas = dynamic(() => import("./SaudiIndustrialAtlas"), { ssr: false });

export type StoryStep = { n: string; title: string; body: string };
export type StoryStrings = {
  title: string;
  overline: string;
  truth: string;                                  // persistent SAMPLE disclosure
  stagesLabel: string;                            // tablist aria-label
  stages: { id: AtlasStageId; label: string }[];  // six lifecycle stages
  dossier: DossierStrings;
  viewMap: string;
  viewList: string;
  listCaption: string;
  listCols: { location: string; industry: string; state: string };
  steps: StoryStep[];
};

export default function StoryPanel({ strings: s, locale, themeLabels }: {
  strings: StoryStrings;
  locale: "ar" | "en";
  themeLabels: { toLight: string; toDark: string };
}) {
  const [mapFailed, setMapFailed] = useState(false);
  const [listView, setListView] = useState(false);
  const [stage, setStage] = useState<AtlasStageId>("plan");

  const tlRef = useRef<AtlasTimeline | null>(null);
  const manualRef = useRef(false);   // user took control via the tablist
  const tabsRef = useRef<(HTMLButtonElement | null)[]>([]);

  // Motion loop runs only while the live atlas is on screen.
  useEffect(() => {
    if (mapFailed || listView) return;
    const tl = createAtlasTimeline(i => { if (!manualRef.current) setStage(STAGE_ORDER[i]); });
    tlRef.current = tl;
    tl.start();
    return () => { tl.stop(); tlRef.current = null; };
  }, [mapFailed, listView]);

  const onInteracting = useCallback((on: boolean) => {
    if (on) tlRef.current?.pause();
    else if (!manualRef.current) tlRef.current?.resume();
  }, []);

  const pickStage = useCallback((id: AtlasStageId) => {
    manualRef.current = true;
    tlRef.current?.pause();
    setStage(id);
  }, []);

  const onTabKey = (e: React.KeyboardEvent, idx: number) => {
    const n = s.stages.length;
    let next = idx;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") next = (idx + 1) % n;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") next = (idx - 1 + n) % n;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = n - 1;
    else return;
    e.preventDefault();
    pickStage(s.stages[next].id);
    tabsRef.current[next]?.focus();
  };

  return (
    <aside className="lg-story">
      <header className="lg-story__head">
        <div className="lg-story__heading">
          <span className="lg-story__title">{s.title}</span>
          <span className="lg-story__overline" dir="ltr">{s.overline}</span>
        </div>
        <ThemeToggle className="lg-iconbtn" labels={themeLabels} />
      </header>

      <div className="lg-story__frame">
        {/* Persistent truth disclosure — never tooltip-hidden (contract L5). */}
        <p className="lg-atlas3d__truth" role="note">{s.truth}</p>

        {/* Map / list toggle — the list is the accessible data alternative. */}
        <div className="lg-atlas3d__viewtoggle" role="group" aria-label={s.viewMap + " / " + s.viewList}>
          <button type="button" className={!listView ? "is-active" : ""}
            aria-pressed={!listView} onClick={() => setListView(false)}>{s.viewMap}</button>
          <button type="button" className={listView ? "is-active" : ""}
            aria-pressed={listView} onClick={() => setListView(true)}>{s.viewList}</button>
        </div>

        {listView ? (
          <div className="lg-atlas3d__list">
            <table>
              <caption>{s.listCaption}</caption>
              <thead>
                <tr>
                  <th scope="col">{s.listCols.location}</th>
                  <th scope="col">{s.listCols.industry}</th>
                  <th scope="col">{s.listCols.state}</th>
                </tr>
              </thead>
              <tbody>
                {NODES.map(n => (
                  <tr key={n.id}>
                    <th scope="row">{n.name[locale]}</th>
                    <td>{n.industry[locale]}</td>
                    <td><span className={`lg-atlas3d__pill lg-atlas3d__pill--${n.halo}`}>{n.sampleState[locale]}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : mapFailed ? (
          <div className="lg-story__fallback"><SaqeelHero /></div>
        ) : (
          <Atlas locale={locale} activeStage={stage} dossierStrings={s.dossier}
            onInteractingChange={onInteracting} onFail={() => setMapFailed(true)} />
        )}
      </div>

      {/* Lifecycle rail — drives the overlays; roving tabindex. */}
      {!listView && !mapFailed && (
        <div className="lg-atlas3d__stages" role="tablist" aria-label={s.stagesLabel}>
          {s.stages.map((st, i) => (
            <button key={st.id} ref={el => { tabsRef.current[i] = el; }} type="button" role="tab"
              aria-selected={stage === st.id} tabIndex={stage === st.id ? 0 : -1}
              className={`lg-atlas3d__stage${stage === st.id ? " is-active" : ""}`}
              onClick={() => pickStage(st.id)} onKeyDown={e => onTabKey(e, i)}>
              <span className="lg-atlas3d__stage-n" dir="ltr">{String(i + 1).padStart(2, "0")}</span>
              <span className="lg-atlas3d__stage-label">{st.label}</span>
            </button>
          ))}
        </div>
      )}

      <div className="lg-story__strip">
        {s.steps.map(step => (
          <div className="lg-story__step" key={step.n}>
            <div className="lg-story__step-head">
              <span className="lg-story__step-badge" dir="ltr">{step.n}</span>
              <span className="lg-story__step-title">{step.title}</span>
            </div>
            <p className="lg-story__step-body">{step.body}</p>
          </div>
        ))}
      </div>
    </aside>
  );
}

