@media (prefers-reduced-motion: reduce) {
  .lg-hero__fence, .lg-hero__pulse, .lg-hero__ping { animation: none; }
}

/* ============================================================================
   CD-001 V7 — PREMIUM 3D SAUDI INDUSTRIAL INSPECTION ATLAS
   Five layers over the Leaflet stack. Tokens only (GLOBAL COLOR LAW): tone is
   carried per node via --tone; color-mix derives tints/shadows from tokens.
   ========================================================================== */

/* ---- persistent truth disclosure (Layer 5) — never tooltip-hidden -------- */
.lg-atlas3d__truth { position: absolute; inset-block-start: 0; inset-inline: 0; z-index: 600;
  margin: 0; padding: 6px var(--ax-space-200); text-align: center;
  font: 700 10px/1.5 var(--ax-font-mono); letter-spacing: 0.12em;
  color: var(--ax-color-warning-strong);
  background: color-mix(in srgb, var(--ax-color-warning) 18%, var(--ax-color-surface));
  border-block-end: 1px solid color-mix(in srgb, var(--ax-color-warning) 40%, transparent); }

/* ---- map / list toggle --------------------------------------------------- */
.lg-atlas3d__viewtoggle { position: absolute; inset-block-start: 36px; inset-inline-end: 10px; z-index: 620;
  display: inline-flex; gap: 2px; padding: 3px; border-radius: var(--ax-radius-full);
  background: color-mix(in srgb, var(--ax-color-surface) 88%, transparent);
  border: 1px solid var(--ax-color-border); backdrop-filter: blur(6px); }
.lg-atlas3d__viewtoggle button { border: none; background: none; cursor: pointer;
  padding: 4px 12px; border-radius: var(--ax-radius-full);
  font: var(--ax-text-caption); font-weight: 600; color: var(--ax-color-text-secondary); }
.lg-atlas3d__viewtoggle button.is-active { background: var(--ax-color-primary); color: var(--ax-color-inverse-text); }
.lg-atlas3d__viewtoggle button:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }

/* ---- Layer 2: terrain relief slab + orientation labels ------------------- */
.lg-atlas3d__terrain-top { fill: color-mix(in srgb, var(--ax-color-primary) 10%, transparent); }
.lg-atlas3d__terrain-shadow { fill: color-mix(in srgb, var(--ax-color-shadow-base) 45%, transparent);
  transform: translateY(6px); }
.lg-atlas3d__orient { transform: translate(-50%, -50%); white-space: nowrap;
  color: var(--ax-color-text-secondary); text-shadow: 0 1px 3px var(--ax-color-canvas); }
.lg-atlas3d__orient--en { font: 500 9px var(--ax-font-sans); letter-spacing: 0.5px; }
.lg-atlas3d__orient--ar { font: 600 11px var(--ax-font-arabic); }

/* ---- Layer 2/4: node structures ------------------------------------------ */
.lg-atlas3d__node { position: relative; inline-size: var(--nw); transform: translate(-50%, -100%);
  display: flex; flex-direction: column; align-items: center; color: var(--tone);
  pointer-events: auto; cursor: pointer; transition: transform var(--ax-motion-fast); }
.lg-atlas3d__node:hover, .lg-atlas3d__node:focus-within { transform: translate(-50%, -100%) scale(1.06); }
.lg-atlas3d__node--arrival { --tone: var(--ax-color-success); }
.lg-atlas3d__node--planned { --tone: var(--ax-color-warning); }
.lg-atlas3d__node--virtual { --tone: var(--ax-color-info); }
.lg-atlas3d__node--route   { --tone: var(--ax-color-primary); }
.lg-atlas3d__halo { position: absolute; inset-block-end: -4px; inset-inline-start: 50%;
  inline-size: calc(var(--nw) + 20px); block-size: 16px; transform: translateX(-50%);
  border-radius: var(--ax-radius-full);
  background: radial-gradient(ellipse at center, color-mix(in srgb, var(--tone) 50%, transparent), transparent 72%); }
.lg-atlas3d__struct { position: relative; inline-size: var(--nw); block-size: var(--nh);
  display: grid; place-items: end center; border-radius: var(--ax-radius-small); }
.lg-atlas3d__struct-flat svg { inline-size: var(--nw); block-size: var(--nh);
  filter: drop-shadow(0 3px 4px color-mix(in srgb, var(--ax-color-shadow-base) 55%, transparent)); }
.lg-atlas3d__struct-img { position: absolute; inset: 0; inline-size: 100%; block-size: 100%;
  object-fit: contain; opacity: 0; transition: opacity var(--ax-motion-standard); }
.lg-atlas3d__anchor { position: absolute; inset-block-end: 0; inset-inline-end: -9px;
  inline-size: 8px; block-size: 32px; opacity: 0.8;
  background: linear-gradient(to top, var(--tone), color-mix(in srgb, var(--tone) 25%, transparent));
  clip-path: polygon(32% 100%, 68% 100%, 58% 0, 42% 0); }
.lg-atlas3d__node-base { inline-size: calc(var(--nw) + 6px); block-size: 4px; margin-block-start: 3px;
  border-radius: var(--ax-radius-full); background: color-mix(in srgb, var(--tone) 40%, transparent); }
.lg-atlas3d__node-label { margin-block-start: 4px; white-space: nowrap;
  color: var(--ax-color-text); text-shadow: 0 1px 4px var(--ax-color-canvas); }
.lg-atlas3d__node-label--en { font: 600 10px var(--ax-font-mono); letter-spacing: 1.5px; }
.lg-atlas3d__node-label--ar { font: 700 13px var(--ax-font-arabic); }
.lg-atlas3d__node:focus-visible { outline: none; }
.lg-atlas3d__node:focus-visible .lg-atlas3d__struct { box-shadow: var(--ax-focus-ring); }

/* ---- Layer 3: journey overlays (illustrative; no red states) ------------- */
.lg-atlas3d__route { animation: lg-atlas-route 24s linear infinite; }
@keyframes lg-atlas-route { to { stroke-dashoffset: -320; } }
.lg-atlas3d__vehicle, .lg-atlas3d__actor, .lg-atlas3d__evidence, .lg-atlas3d__cue {
  position: absolute; transform: translate(-50%, -50%); opacity: 0; pointer-events: none;
  transition: opacity var(--ax-motion-standard); }
.lg-atlas3d__vehicle.is-on, .lg-atlas3d__actor.is-on, .lg-atlas3d__evidence.is-on, .lg-atlas3d__cue.is-on { opacity: 1; }
.lg-atlas3d__vehicle { display: grid; place-items: center; inline-size: 28px; block-size: 20px;
  border-radius: var(--ax-radius-small); background: var(--ax-color-surface);
  border: 1.5px solid var(--ax-color-primary); color: var(--ax-color-primary-hover);
  box-shadow: var(--ax-shadow-raised); }
.lg-atlas3d__actor { display: grid; place-items: center; inline-size: 26px; block-size: 26px;
  border-radius: var(--ax-radius-full); background: var(--ax-color-success);
  color: var(--ax-color-inverse-text); border: 2px solid var(--ax-color-canvas); box-shadow: var(--ax-shadow-raised); }
.lg-atlas3d__evidence { display: grid; place-items: center; inline-size: 20px; block-size: 20px;
  border-radius: var(--ax-radius-full); background: var(--ax-color-success);
  color: var(--ax-color-inverse-text); border: 2px solid var(--ax-color-canvas); }
.lg-atlas3d__cue { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap;
  padding: 2px 8px; border-radius: var(--ax-radius-full); font: 700 11px var(--ax-font-mono);
  background: var(--ax-color-surface); border: 1px solid var(--ax-color-border); box-shadow: var(--ax-shadow-raised); }
.lg-atlas3d__cue--review { color: var(--ax-color-primary-hover); }
.lg-atlas3d__cue--seal { color: var(--ax-color-success); }
.lg-atlas3d__geofence { position: absolute; transform: translate(-50%, -50%); opacity: 0;
  inline-size: calc(var(--fence-r) * 2); block-size: calc(var(--fence-r) * 2);
  border-radius: var(--ax-radius-full); border: 1.5px dashed var(--ax-color-success);
  background: radial-gradient(circle, color-mix(in srgb, var(--ax-color-success) 12%, transparent), transparent 70%);
  transition: opacity var(--ax-motion-standard); }
.lg-atlas3d__geofence.is-on { opacity: 1; }
.lg-atlas3d__geofence.pulse { animation: lg-atlas-fence 0.6s ease-out 1; }
@keyframes lg-atlas-fence {
  0% { transform: translate(-50%, -50%) scale(0.85); }
  100% { transform: translate(-50%, -50%) scale(1); } }

/* ---- Layer 4: dossier ---------------------------------------------------- */
.lg-atlas3d__dossier { position: absolute; inset-block-start: 44px; inset-inline-end: 10px; z-index: 650;
  inline-size: min(280px, 72%); padding: var(--ax-space-200);
  border-radius: var(--ax-radius-large); border: 1px solid var(--ax-color-border);
  background: color-mix(in srgb, var(--ax-color-surface) 94%, transparent); backdrop-filter: blur(10px);
  box-shadow: var(--ax-shadow-overlay); animation: lg-atlas-dossier 0.18s ease-out; }
@keyframes lg-atlas-dossier { from { opacity: 0; transform: translateY(-4px); } }
.lg-atlas3d__dossier--locked { border-color: var(--ax-color-primary); }
.lg-atlas3d__dossier-head { display: flex; align-items: center; gap: var(--ax-space-100); }
.lg-atlas3d__dossier-dot { inline-size: 10px; block-size: 10px; border-radius: var(--ax-radius-full); flex-shrink: 0; }
.lg-atlas3d__dossier-name { font: 700 15px var(--ax-font-sans); color: var(--ax-color-text); }
.lg-atlas3d__dossier-close { margin-inline-start: auto; border: none; background: none; cursor: pointer;
  padding: 4px; line-height: 1; font-size: 14px; color: var(--ax-color-text-secondary);
  border-radius: var(--ax-radius-small); }
.lg-atlas3d__dossier-close:hover { color: var(--ax-color-text); background: var(--ax-color-neutral-tint); }
.lg-atlas3d__dossier-close:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }
.lg-atlas3d__dossier-body { margin: var(--ax-space-150) 0 0; display: flex; flex-direction: column; gap: var(--ax-space-100); }
.lg-atlas3d__dossier-row { display: flex; flex-direction: column; gap: 1px; }
.lg-atlas3d__dossier-row dt { font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }
.lg-atlas3d__dossier-row dd { margin: 0; font: var(--ax-text-body); color: var(--ax-color-text); }
.lg-atlas3d__dossier-state { font-weight: 700; }
.lg-atlas3d__dossier-sample { margin: var(--ax-space-150) 0 0; padding-block-start: var(--ax-space-100);
  border-block-start: 1px solid var(--ax-color-border);
  font: 600 10px/1.4 var(--ax-font-mono); letter-spacing: 0.06em; color: var(--ax-color-warning-strong); }

/* ---- lifecycle rail (6-stage tablist) ------------------------------------ */
.lg-atlas3d__stages { display: flex; gap: var(--ax-space-050); }
.lg-atlas3d__stage { flex: 1 1 0; min-inline-size: 0; display: flex; flex-direction: column; gap: 2px;
  padding: var(--ax-space-100) var(--ax-space-150); text-align: start; cursor: pointer;
  background: var(--ax-color-surface); border: 1px solid var(--ax-color-border);
  border-radius: var(--ax-radius-standard); color: var(--ax-color-text-secondary);
  transition: border-color var(--ax-motion-fast), color var(--ax-motion-fast); }
.lg-atlas3d__stage:hover { border-color: var(--ax-color-primary); }
.lg-atlas3d__stage.is-active { border-color: var(--ax-color-primary); color: var(--ax-color-text);
  background: color-mix(in srgb, var(--ax-color-primary) 10%, var(--ax-color-surface)); }
.lg-atlas3d__stage:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }
.lg-atlas3d__stage-n { font: 700 10px var(--ax-font-mono); color: var(--ax-color-primary-hover); }
.lg-atlas3d__stage-label { font: 600 12px var(--ax-font-sans); overflow: hidden; text-overflow: ellipsis; }

/* ---- list alternative (same data source) --------------------------------- */
.lg-atlas3d__list { position: absolute; inset: 0; inset-block-start: 30px; overflow: auto;
  padding: var(--ax-space-250) var(--ax-space-200) var(--ax-space-200);
  background: var(--ax-color-canvas); }
.lg-atlas3d__list table { inline-size: 100%; border-collapse: collapse; }
.lg-atlas3d__list caption { text-align: start; margin-block-end: var(--ax-space-150);
  font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }
.lg-atlas3d__list th, .lg-atlas3d__list td { text-align: start;
  padding: var(--ax-space-100) var(--ax-space-150); border-block-end: 1px solid var(--ax-color-border); }
.lg-atlas3d__list thead th { font: var(--ax-text-caption); font-weight: 700; color: var(--ax-color-text-secondary); }
.lg-atlas3d__list tbody th { font: var(--ax-text-body-strong); color: var(--ax-color-text); white-space: nowrap; }
.lg-atlas3d__list tbody td { font: var(--ax-text-body); color: var(--ax-color-text-secondary); }
.lg-atlas3d__pill { display: inline-block; padding: 2px 10px; border-radius: var(--ax-radius-full);
  font: var(--ax-text-caption); font-weight: 600; }
.lg-atlas3d__pill--arrival { background: var(--ax-color-success-tint); color: var(--ax-color-success-strong); }
.lg-atlas3d__pill--planned { background: var(--ax-color-warning-tint); color: var(--ax-color-warning-strong); }
.lg-atlas3d__pill--virtual { background: var(--ax-color-info-tint); color: var(--ax-color-info); }
.lg-atlas3d__pill--route   { background: var(--ax-color-primary-tint); color: var(--ax-color-primary-hover); }

/* ---- responsive: dossier becomes a bottom sheet on narrow frames --------- */
@media (max-width: 1200px) {
  .lg-atlas3d__dossier { inset-block: auto 8px; inset-inline: 8px; inline-size: auto; }
}

/* ---- reduced motion: loop off; stepped states only ----------------------- */
@media (prefers-reduced-motion: reduce) {
  .lg-atlas3d__route { animation: none; }
  .lg-atlas3d__geofence.pulse { animation: none; }
  .lg-atlas3d__node,
  .lg-atlas3d__vehicle, .lg-atlas3d__actor, .lg-atlas3d__evidence,
  .lg-atlas3d__cue, .lg-atlas3d__geofence, .lg-atlas3d__struct-img { transition: none; }
  .lg-atlas3d__dossier { animation: none; }
}

