tool_input.content:
import { test, expect } from "@playwright/test";

// CD-001 V7 Atlas — runtime interaction proof for the premium 3D Saudi
// Industrial Inspection Atlas on /login. Demonstrates the claims the design
// handoff requires before implementation is accepted: atlas mounts,
// persistent SAMPLE truth banner, lifecycle tablist drives overlays,
// hover/focus + click-lock + Esc dossier, list alternative, and sign-in
// remaining usable throughout. Public page — no auth needed.

test.beforeEach(async ({ context }) => {
  await context.addCookies([{ name: "locale", value: "en", url: "http://127.0.0.1:3210" }]);
});

test("atlas mounts with a persistent truth banner and a usable sign-in form", async ({ page }) => {
  const errors: string[] = [];
  page.on("pageerror", e => errors.push(String(e)));

  await page.goto("/login");

  // Truth banner is present and never hidden.
  const truth = page.locator(".lg-atlas3d__truth");
  await expect(truth).toBeVisible();
  await expect(truth).toContainText(/NO LIVE OPERATIONAL DATA/i);

  // Credential form is usable before/while the atlas is up.
  await expect(page.locator("#email")).toBeEnabled();
  await expect(page.getByRole("button", { name: /Sign In/i })).toBeEnabled();

  // Atlas layer 2 mounts (nodes render even if external tiles are blocked).
  await expect(page.locator(".lg-atlas3d__node").first()).toBeVisible({ timeout: 15000 });
  expect(await page.locator(".lg-atlas3d__node").count()).toBe(9);

  expect(errors, errors.join("\n")).toEqual([]);
});

test("lifecycle tablist drives the overlays (stepped, deterministic)", async ({ page }) => {
  await page.goto("/login");
  const tabs = page.getByRole("tab");
  await expect(tabs).toHaveCount(6);

  // Selecting INSPECT (manual → stops the auto loop) reveals evidence overlays.
  await page.getByRole("tab", { name: /Inspect/i }).click();
  await expect(page.getByRole("tab", { name: /Inspect/i })).toHaveAttribute("aria-selected", "true");
  await expect(page.locator(".lg-atlas3d__evidence.is-on").first()).toBeVisible();

  // DECIDE reveals the decision seal cue.
  await page.getByRole("tab", { name: /Decide/i }).click();
  await expect(page.locator(".lg-atlas3d__cue--seal.is-on")).toBeVisible();
});

test("dossier: hover/focus opens, click locks (role=dialog), Esc closes", async ({ page }) => {
  await page.goto("/login");
  const node = page.locator(".lg-atlas3d__node").first();
  await expect(node).toBeVisible({ timeout: 15000 });

  await node.hover();
  await expect(page.locator(".lg-atlas3d__dossier")).toBeVisible();
  await expect(page.locator(".lg-atlas3d__dossier-sample")).toContainText(/Sample/i);

  await node.click();
  await expect(page.getByRole("dialog")).toBeVisible();

  await page.getByRole("dialog").getByRole("button", { name: /Close/i }).click();
  await expect(page.getByRole("dialog")).toHaveCount(0);
});

test("list alternative exposes the same nine nodes as a table", async ({ page }) => {
  await page.goto("/login");
  await page.getByRole("button", { name: /^List$/ }).click();
  const rows = page.locator(".lg-atlas3d__list tbody tr");
  await expect(rows).toHaveCount(9);
  await expect(page.locator(".lg-atlas3d__list caption")).toContainText(/illustrative/i);
});

