import { test, expect } from "@playwright/test";

// CD-003 / AUTH-03 — role resolution + no-workspace fallback. Behavioral
// proof that the ROLE_HOME edit (added explicit "admin" match, replaced the
// blind /admin fallback with /launch/no-workspace) doesn't change routing
