tool_input.content:
-- CD-021 (SCR-WEB-110 /planning/bulk) — atomic bulk publish.
--
-- Resolves the HANDOFF_BLOCKED atomicity leg in outputs/cd-021.
-- Before: apps/web/src/app/planning/bulk/actions.ts performed 6 sequential
-- writes (plan, visits, assignments, visits->published, plan->published,
-- notifications) with NO transaction. A failure mid-way left rows the UI had
-- already reported as published — a violation of P03 "partial publish
-- prohibited". The comment claimed atomicity that did not exist.
--
-- This function wraps the whole write set in ONE plpgsql body, so any error
-- rolls the entire operation back (true all-or-nothing). It is SECURITY
-- INVOKER: it runs as the calling planner, so every insert/update is still
-- filtered by the existing RLS policies — NO privileged bypass (per
-- outputs/cd-021/WIRING_MAP_CD-021.csv "no client-side bypass" / "RLS all
-- tables; planner").
--
-- Validation (empty selection, unpublished package, invalid window, M02-012
-- duplicates, M01-029 inspector eligibility/double-booking) stays in the
-- server action, which owns the catalogued, human-readable blocker messages.
-- This function assumes the caller passed an already-validated set and only
-- guarantees the writes are atomic.
--
-- No schema/column/enum/RLS/transition changes. Canonical transitions
-- (draft -> published) are unchanged; this only makes them atomic.

create or replace function publish_bulk_plan(
  p_factory_ids        uuid[],
  p_package_version_id uuid,
  p_window_start       timestamptz,
  p_window_end         timestamptz,
  p_visit_type         text,
  p_notes              text,
  p_manual             jsonb,   -- { "<factory_id>": "<inspector_id>" } manual picks (M01-029)
  p_auto_pool          uuid[]   -- ordered inspector pool for round-robin of the rest (ENG-05)
) returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_plan_id   uuid;
  v_fid       uuid;
  v_visit_id  uuid;
  v_inspector uuid;
  v_method    assignment_method;
  v_rr        int := 0;               -- round-robin cursor over p_auto_pool
  v_pool_len  int := coalesce(array_length(p_auto_pool, 1), 0);
begin
  if p_factory_ids is null or array_length(p_factory_ids, 1) is null then
    raise exception 'publish_bulk_plan: empty factory set' using errcode = 'P0001';
  end if;

  -- plan (bulk method, draft first so the same canonical transition applies)
  insert into visit_plans (method, status, created_by, criteria)
  values ('bulk', 'draft', auth.uid(),
          jsonb_build_object('selected', array_length(p_factory_ids, 1)))
  returning id into v_plan_id;

  -- one visit + one assignment per factory
  foreach v_fid in array p_factory_ids loop
    insert into visits (
      visit_plan_id, factory_id, visit_type, execution_mode,
      planning_status, window_start, window_end, package_version_id, notes
    ) values (
      v_plan_id, v_fid, p_visit_type, 'physical',
      'draft', p_window_start, p_window_end, p_package_version_id, p_notes
    ) returning id into v_visit_id;

    -- manual pick honored; otherwise round-robin over the auto pool (ENG-05)
    if p_manual ? v_fid::text then
      v_inspector := (p_manual ->> v_fid::text)::uuid;
      v_method    := 'manual';
    elsif v_pool_len > 0 then
      v_inspector := p_auto_pool[(v_rr % v_pool_len) + 1];
      v_rr        := v_rr + 1;
      v_method    := 'automatic';
    else
      raise exception 'publish_bulk_plan: no inspector available for factory %', v_fid
        using errcode = 'P0001';
    end if;

    insert into assignments (visit_id, inspector_id, method)
    values (v_visit_id, v_inspector, v_method);
  end loop;

  -- canonical transition draft -> published (atomic with the inserts above)
  update visits      set planning_status = 'published' where visit_plan_id = v_plan_id;
  update visit_plans set status = 'published', published_at = now() where id = v_plan_id;

  -- assignment notifications (same semantics as before; now inside the txn)
  insert into notifications (event_key, recipient, payload, channel)
  select 'assignment', a.inspector_id,
         jsonb_build_object('visit_id', a.visit_id), 'push'
  from assignments a
  join visits v on v.id = a.visit_id
  where v.visit_plan_id = v_plan_id;

  return v_plan_id;
end;
$$;

comment on function publish_bulk_plan is
  'CD-021: atomic bulk-plan publish (SECURITY INVOKER, RLS-enforced). Replaces the '
  'non-transactional 6-write sequence in planning/bulk/actions.ts. All-or-nothing per P03.';

grant execute on function publish_bulk_plan to authenticated;

"use server";
import { redirect } from "next/navigation";
import { supabaseServer } from "@/lib/supabase-server";

export type BulkResult = { error?: string };

// CD-021: neutral, catalogued failure copy. Raw Supabase/provider error text
// must NEVER reach the UI (it leaks schema/internal detail) — it is logged
// server-side and the operator sees governed language only.
const NEUTRAL_PUBLISH_ERROR =
  "Publishing failed — the plan was not created and no visits were scheduled. " +
  "Nothing was published. Please try again; if it keeps failing, contact support.";

export async function publishBulkPlan(_: BulkResult, formData: FormData): Promise<BulkResult> {
  const sb = await supabaseServer();
  const { data: { user } } = await sb.auth.getUser();
  if (!user) return { error: "Session expired." };
  let factoryIds = formData.getAll("factory_id").map(String);
  const package_version_id = String(formData.get("package_version_id") ?? "");
  const window_start = String(formData.get("window_start") ?? "");
  const window_end = String(formData.get("window_end") ?? "");
  const visit_type = String(formData.get("visit_type") ?? "periodic");
  const skipDuplicates = formData.get("skip_duplicates") === "1";
  const notesRaw = String(formData.get("notes") ?? "").trim();
  const notes = notesRaw === "" ? null : notesRaw;
  // Manual per-visit inspector picks (M01-029): inspector_<factoryId> = user_id | "" (auto)
  const picks = new Map<string, string>();
  for (const fid of factoryIds) {
    const p = String(formData.get(`inspector_${fid}`) ?? "");
    if (p) picks.set(fid, p);
  }

  const blockers: string[] = [];
  if (factoryIds.length === 0) blockers.push("No factories selected — only selected targets proceed (M01-005)");
  if (!package_version_id) blockers.push("No published package (ERR-PUB-001)");
  if (!window_start || !window_end || new Date(window_end) <= new Date(window_start)) blockers.push("Invalid window (FLD-PLAN-005)");
  // per-row duplicate check (P01: duplicates flagged; conflicts listed, skip allowed)
  const { data: dups } = await sb.from("visits").select("factory_id")
    .in("factory_id", factoryIds).eq("visit_type", visit_type).in("planning_status", ["draft", "published", "returned"]);
  const dupSet = new Set((dups ?? []).map(d => d.factory_id));
  if (dupSet.size) {
    if (skipDuplicates) {
      factoryIds = factoryIds.filter(fid => !dupSet.has(fid));
      if (factoryIds.length === 0) blockers.push("All selected factories have an active duplicate visit — nothing left to publish (M02-012)");
    } else {
      blockers.push(`${dupSet.size} selected factories already have an active ${visit_type} visit (M02-012) — deselect them or choose skip`);
    }
  }

  // inspectors pool (ENG-05 automatic; capacity checks deepen in B7)
  const { data: inspRows } = await sb.from("user_roles").select("user_id").eq("role_key", "inspector");
  const inspectors = (inspRows ?? []).map(r => r.user_id);
  if (!inspectors.length) blockers.push("No eligible inspector (P02 failure control)");

  // Manual pick validation (M01-029): eligibility + same-window double-booking conflicts.
  const pool = new Set(inspectors);
  const chosen = [...new Set([...picks.values()])];
  for (const insp of chosen) {
    if (!pool.has(insp)) blockers.push(`Selected inspector is not in the eligible inspector pool (M01-029): ${insp.slice(0, 8)}`);
  }
  if (chosen.length && window_start && window_end) {
    // Existing active assignments whose visit window overlaps this plan's window (visits embed is TO-ONE).
    const { data: conflicts } = await sb.from("assignments")
      .select("inspector_id, visits!inner(id, window_start, window_end, planning_status)")
      .in("inspector_id", chosen)
      .in("visits.planning_status", ["draft", "published", "returned"])
      .lt("visits.window_start", window_end)
      .gt("visits.window_end", window_start);
    if ((conflicts ?? []).length) {
      const byInsp = new Map<string, number>();
      for (const c of conflicts!) byInsp.set(c.inspector_id, (byInsp.get(c.inspector_id) ?? 0) + 1);
      const { data: names } = await sb.from("profiles").select("user_id, full_name").in("user_id", [...byInsp.keys()]);
      const nameOf = new Map((names ?? []).map(n => [n.user_id, n.full_name]));
      for (const [insp, n] of byInsp) {
        blockers.push(`${nameOf.get(insp) ?? insp.slice(0, 8)} is already booked on ${n} overlapping visit(s) in this window (M01-029 double-booking)`);
      }
    }
  }
  if (blockers.length) return { error: blockers.join(" · ") };

  // CD-021: atomic publish. publish_bulk_plan (migration 0026) performs every
  // write — plan, visits, assignments, draft->published transition,
  // notifications — inside one SECURITY INVOKER transaction. On any error the
  // whole operation rolls back: no plan, no visits, no half-published state
  // (P03 "partial publish prohibited"). RLS is still enforced because the
  // function runs as the calling planner.
  const manual: Record<string, string> = {};
  for (const [fid, insp] of picks) manual[fid] = insp;
  const { error } = await sb.rpc("publish_bulk_plan", {
    p_factory_ids: factoryIds,
    p_package_version_id: package_version_id,
    p_window_start: window_start,
    p_window_end: window_end,
    p_visit_type: visit_type,
    p_notes: notes,
    p_manual: manual,
    p_auto_pool: inspectors,
  });
  if (error) {
    // Log the real cause server-side; return catalogued neutral copy only.
    console.error("[CD-021] publish_bulk_plan failed:", error.message, error.code);
    return { error: NEUTRAL_PUBLISH_ERROR };
  }
  redirect("/visits");
}

// CD-021 (SCR-WEB-110) — eligibility ledger strip (design frame 1a).
// The signature of the Targeting Lens: denominator + eligible + excluded shown
// together so a planner always sees what the criteria kept, dropped, and out of
// how many — never a bare result count. Server-rendered; pure counts (no AI,
// no inference). Freshness is the real factories.source_synced_at (FND-013):
// we show the actual oldest sync time and how many rows are missing it. We do
// NOT classify "stale" — no governed staleness threshold exists in
// engine_settings, and inventing one is prohibited.

export type LedgerStrings = {
  heading: string;
  denominator: string;
  eligible: string;
  excluded: string;
  freshness: string;
  freshnessNever: string;   // "no sync timestamp"
  freshnessMissing: string; // "{n} missing sync"
  focusContribution: string; // "{n} from focused condition" (reserved for criteria focus)
};

export default function EligibilityLedger({
  denominator, eligible, oldestSyncedAt, missingSync, strings,
}: {
  denominator: number;
  eligible: number;
  oldestSyncedAt: string | null;
  missingSync: number;
  strings: LedgerStrings;
}) {
  const excluded = Math.max(0, denominator - eligible);
  // Factual relative age — no threshold styling.
  const freshnessLabel = oldestSyncedAt
    ? new Date(oldestSyncedAt).toISOString().slice(0, 16).replace("T", " ")
    : strings.freshnessNever;

  return (
    <section className="ax-surface" aria-label={strings.heading}
      style={{ padding: "var(--ax-space-300)", display: "flex", flexWrap: "wrap", gap: "var(--ax-space-400)", alignItems: "flex-end" }}>
      <div>
        <span className="ax-caption">{strings.denominator}</span>
        <div className="ax-numeric" aria-live="polite"><strong style={{ fontSize: "var(--ax-font-size-400, 1.5rem)" }}>{denominator}</strong></div>
      </div>
      <div>
        <span className="ax-caption">{strings.eligible}</span>
        <div className="ax-numeric" aria-live="polite">
          <span className="ax-lozenge ax-lozenge--success">✓ {eligible}</span>
        </div>
      </div>
      <div>
        <span className="ax-caption">{strings.excluded}</span>
        <div className="ax-numeric" aria-live="polite">
          <span className="ax-lozenge ax-lozenge--neutral">− {excluded}</span>
        </div>
      </div>
      <div style={{ marginInlineStart: "auto" }}>
        <span className="ax-caption">{strings.freshness}</span>
        <div className="ax-caption ax-numeric">
          <bdi>{freshnessLabel}</bdi>
          {missingSync > 0 && (
            <> · <span className="ax-lozenge ax-lozenge--warning">⚠ {strings.freshnessMissing.replace("{n}", String(missingSync))}</span></>
          )}
        </div>
      </div>
    </section>
  );
}

// CD-021 (SCR-WEB-110) — distribution panels (design frame 1a).
// List-first, accessible distributions of the eligible set across region, risk
// band and activity class. Every panel shows its denominator and an explicit
// "unknown" bucket (null/blank values are surfaced, never dropped). Pure counts
// over the already-evaluated set — no AI, no ranking, no auto-selection.
// A map view is a later optional channel (COMPONENT_MAP GeoMap PRESERVE); the
// list is the equivalent primary channel and is always present.

export type Bucket = { label: string; count: number; unknown?: boolean };
export type Distribution = { key: string; heading: string; total: number; buckets: Bucket[] };

export type DistributionStrings = {
  heading: string;
  ofDenominator: string; // "of {n}"
  unknown: string;       // "unknown"
  riskAdvisory: string;  // ENG-04 advisory label
};

function Panel({ dist, strings }: { dist: Distribution; strings: DistributionStrings }) {
  const max = Math.max(1, ...dist.buckets.map(b => b.count));
  return (
    <section className="ax-surface" aria-label={dist.heading}
      style={{ padding: "var(--ax-space-300)", display: "flex", flexDirection: "column", gap: "var(--ax-space-150)" }}>
      <div className="ax-row" style={{ justifyContent: "space-between", alignItems: "baseline" }}>
        <h4 style={{ margin: 0 }}>{dist.heading}</h4>
        <span className="ax-caption ax-numeric">{strings.ofDenominator.replace("{n}", String(dist.total))}</span>
      </div>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: "var(--ax-space-100)" }}>
        {dist.buckets.map(b => {
          const pct = Math.round((b.count / max) * 100);
          return (
            <li key={b.label} className="ax-row" style={{ gap: "var(--ax-space-150)", alignItems: "center" }}>
              <span style={{ minInlineSize: 120, flexShrink: 0 }}>
                {b.unknown ? <span className="ax-lozenge ax-lozenge--warning">? {strings.unknown}</span> : <bdi>{b.label}</bdi>}
              </span>
              <span aria-hidden="true" style={{
                blockSize: 8, inlineSize: `${pct}%`, minInlineSize: 2,
                background: "var(--ax-color-accent)", borderRadius: "var(--ax-radius-small)",
              }} />
              <span className="ax-numeric ax-caption" style={{ marginInlineStart: "auto" }}>{b.count}</span>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

export default function DistributionPanels({ distributions, strings }: {
  distributions: Distribution[];
  strings: DistributionStrings;
}) {
  return (
    <section aria-label={strings.heading}
      style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(240px,1fr))", gap: "var(--ax-space-200)" }}>
      {distributions.map(d => (
        <div key={d.key}>
          <Panel dist={d} strings={strings} />
          {d.key === "risk_band" && <p className="ax-caption" style={{ marginBlockStart: "var(--ax-space-100)" }}>{strings.riskAdvisory}</p>}
        </div>
      ))}
    </section>
  );
}

