"use client";
import { useActionState, useEffect, useMemo, useRef, useState } from "react";
import { publishBulkPlan, type BulkResult } from "./actions";

// CD-021 (SCR-WEB-110) — evidence table + persistent selection (frames 1a/1d).
// The targeting screen is about WHICH factories, with the provenance to trust
// the choice. Inspector assignment and per-visit config move to the P02 review
// step (COMPONENT_MAP relocation) — here every selected visit auto-assigns
// round-robin at publish (the atomic RPC owns that). Pagination, filter and
// selection are client-side over the criteria-narrowed eligible set so
// selection persists across paging and filtering; selection also survives
// server navigations via sessionStorage and is reconciled on mount so a
// criteria change that drops selected rows prompts an explicit confirmation
// (never a silent drop).
type F = {
  id: string; factory_code: string; name: string; cr_number: string;
  city: string | null; region: string | null; risk_band: string | null; risk_score: number | null;
  official_lat: number | null; official_lng: number | null; source_synced_at: string | null;
  visits: { planning_status: string; visit_type: string }[];
};
type P = { id: string; version_label: string; packages: { code: string } };

export type BulkFormStrings = {
  colFactory: string; colCr: string; colCity: string; colRisk: string; colEligibility: string;
  colProvenance: string; colDataQuality: string;
  selectFactory: string; eligible: string; duplicate: string; riskAdvisory: string;
  filterLabel: string; filterPlaceholder: string; resultsCount: string;
  selectVisible: string; selectAllResults: string; clearSelection: string;
  pagePrev: string; pageNext: string; pageStatus: string;
  provSynced: string; provNoSync: string;
  dqComplete: string; dqNoLocation: string; dqUnknownRisk: string;
  selectionBar: string; readyPackage: string; readyWindow: string; readyNothing: string;
  invalidTitle: string; invalidBody: string; invalidKeep: string; invalidClear: string;
  visitType: string; typePeriodic: string; packageLabel: string; windowStart: string; windowEnd: string;
  notes: string; notesPlaceholder: string; assignmentNote: string;
  conflictsTitle: string; conflictLine: string; skipDuplicates: string;
  summaryTitle: string; summarySelected: string; summaryByBand: string; summaryByRegion: string;
  summaryType: string; summaryMode: string; summaryModePhysical: string; summaryEmpty: string;
  blockedTitle: string; publish: string; publishing: string;
  riskBands: Record<string, string>;
};

const PAGE_SIZE = 25;
const SEL_KEY = "cd021-bulk-selection";

const dupOf = (f: F) => f.visits.some(v => ["draft", "published", "returned"].includes(v.planning_status) && v.visit_type === "periodic");

export default function BulkForm({ factories, packages, strings }: { factories: F[]; packages: P[]; strings: BulkFormStrings }) {
  const [state, formAction, pending] = useActionState<BulkResult, FormData>(publishBulkPlan, {});
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [q, setQ] = useState("");
  const [page, setPage] = useState(0);
  const [windowStart, setWindowStart] = useState("");
  const [windowEnd, setWindowEnd] = useState("");
  const [skipDuplicates, setSkipDuplicates] = useState(false);
  const [notes, setNotes] = useState("");
  const [invalidDropped, setInvalidDropped] = useState(0);
  const isFirstRender = useRef(true);
  const [resetKey, setResetKey] = useState(0);

  const idSet = useMemo(() => new Set(factories.map(f => f.id)), [factories]);

  // Reconcile any persisted selection against the CURRENT eligible set. Ids that
  // no longer match (e.g. after a criteria change) are dropped and surfaced for
  // explicit confirmation — never silently kept or dropped.
  useEffect(() => {
    let stored: string[] = [];
    try { stored = JSON.parse(sessionStorage.getItem(SEL_KEY) ?? "[]"); } catch { stored = []; }
    if (!Array.isArray(stored) || stored.length === 0) return;
    const valid = stored.filter(id => idSet.has(id));
    const dropped = stored.length - valid.length;
    setSelected(new Set(valid));
    if (dropped > 0) setInvalidDropped(dropped);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { try { sessionStorage.setItem(SEL_KEY, JSON.stringify([...selected])); } catch { /* private mode */ } }, [selected]);
  useEffect(() => { if (isFirstRender.current) { isFirstRender.current = false; return; } setResetKey(k => k + 1); }, [state]);

  const filtered = useMemo(() => {
    const needle = q.trim().toLowerCase();
    if (!needle) return factories;
    return factories.filter(f =>
      [f.name, f.factory_code, f.cr_number, f.city ?? "", f.region ?? ""].some(s => s.toLowerCase().includes(needle)));
  }, [factories, q]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const clampedPage = Math.min(page, pageCount - 1);
  const pageRows = filtered.slice(clampedPage * PAGE_SIZE, clampedPage * PAGE_SIZE + PAGE_SIZE);

  const toggle = (id: string, on: boolean) => setSelected(s => { const n = new Set(s); if (on) n.add(id); else n.delete(id); return n; });
  const selectVisible = () => setSelected(s => { const n = new Set(s); for (const f of pageRows) if (!dupOf(f)) n.add(f.id); return n; });
  const selectAllResults = () => setSelected(s => { const n = new Set(s); for (const f of filtered) if (!dupOf(f)) n.add(f.id); return n; });
  const clearSelection = () => setSelected(new Set());

  const sel = factories.filter(f => selected.has(f.id));
  const countBy = (keyOf: (f: F) => string) => { const o: Record<string, number> = {}; for (const f of sel) { const k = keyOf(f); o[k] = (o[k] ?? 0) + 1; } return o; };
  const byBand = countBy(f => f.risk_band ?? "—");
  const byRegion = countBy(f => f.region ?? "—");
  const windowValid = !!windowStart && !!windowEnd && new Date(windowEnd) > new Date(windowStart);
  const packageValid = packages.length > 0;

  const provenance = (f: F) => f.source_synced_at
    ? strings.provSynced.replace("{d}", new Date(f.source_synced_at).toISOString().slice(0, 10))
    : strings.provNoSync;
  const dataQuality = (f: F) => {
    const flags: { label: string; kind: string }[] = [];
    if (f.official_lat == null || f.official_lng == null) flags.push({ label: strings.dqNoLocation, kind: "critical" });
    if (f.risk_band == null) flags.push({ label: strings.dqUnknownRisk, kind: "warning" });
    return flags;
  };

  return (
    <form action={formAction} className="ax-stack" style={{ gap: "var(--ax-space-300)" }}>
      {invalidDropped > 0 && (
        <div className="ax-banner ax-banner--warning" role="alertdialog" aria-label={strings.invalidTitle}>
          <div>
            <strong>{strings.invalidTitle}</strong>
            <p>{strings.invalidBody.replace("{n}", String(invalidDropped))}</p>
            <div className="ax-row" style={{ gap: "var(--ax-space-150)" }}>
              <button type="button" className="ax-btn ax-btn--secondary" onClick={() => setInvalidDropped(0)}>{strings.invalidKeep}</button>
              <button type="button" className="ax-btn ax-btn--subtle" onClick={() => { clearSelection(); setInvalidDropped(0); }}>{strings.invalidClear}</button>
            </div>
          </div>
        </div>
      )}

      <div className="ax-row" style={{ gap: "var(--ax-space-150)", flexWrap: "wrap", alignItems: "flex-end" }}>
        <div className="ax-field" style={{ maxInlineSize: 280, flex: 1 }}>
          <label className="ax-field__label" htmlFor="bulk-filter">{strings.filterLabel}</label>
          <input id="bulk-filter" className="ax-input" value={q} onChange={e => { setQ(e.target.value); setPage(0); }} placeholder={strings.filterPlaceholder} />
        </div>
        <button type="button" className="ax-btn ax-btn--secondary" onClick={selectVisible}>{strings.selectVisible}</button>
        <button type="button" className="ax-btn ax-btn--secondary" onClick={selectAllResults}>{strings.selectAllResults}</button>
        <span className="ax-caption ax-numeric" role="status" aria-live="polite">{strings.resultsCount.replace("{n}", String(filtered.length))}</span>
      </div>

      <div className="ax-tablewrap"><table className="ax-table">
        <thead><tr>
          <th style={{ inlineSize: 36 }}></th>
          <th>{strings.colFactory}</th><th>{strings.colCr}</th><th>{strings.colCity}</th>
          <th className="ax-td-num">{strings.colRisk}</th><th>{strings.colEligibility}</th>
          <th>{strings.colProvenance}</th><th>{strings.colDataQuality}</th>
        </tr></thead>
        <tbody>
          {pageRows.map(f => {
            const dup = dupOf(f);
            const dq = dataQuality(f);
            return (
              <tr key={f.id}>
                <td><input type="checkbox" disabled={dup} checked={selected.has(f.id)} onChange={e => toggle(f.id, e.target.checked)} aria-label={strings.selectFactory.replace("{name}", f.name)} /></td>
                <td><a href={`/factories/${f.id}`} target="_blank" rel="noreferrer"><strong>{f.name}</strong></a> <span className="ax-caption ax-numeric"><bdi>{f.factory_code}</bdi></span></td>
                <td className="ax-numeric"><bdi>{f.cr_number}</bdi></td>
                <td>{f.city ?? "—"}</td>
                <td className="ax-td-num"><span className={`ax-lozenge ${f.risk_band === "high" ? "ax-lozenge--critical" : f.risk_band === "medium" ? "ax-lozenge--warning" : "ax-lozenge--success"}`}>{(f.risk_band && strings.riskBands[f.risk_band]) ?? "—"} · {f.risk_score ?? "?"}</span></td>
                <td>{dup ? <span className="ax-lozenge ax-lozenge--critical">⛔ {strings.duplicate}</span> : <span className="ax-lozenge ax-lozenge--success">✓ {strings.eligible}</span>}</td>
                <td className="ax-caption ax-numeric"><span className="ax-freshness"><bdi>{provenance(f)}</bdi></span></td>
                <td>{dq.length === 0
                  ? <span className="ax-caption">{strings.dqComplete}</span>
                  : dq.map(d => <div key={d.label}><span className={`ax-lozenge ax-lozenge--${d.kind}`}>{d.kind === "critical" ? "⛔" : "⚠"} {d.label}</span></div>)}</td>
              </tr>
            );
          })}
        </tbody>
      </table></div>
      <p className="ax-caption">{strings.riskAdvisory}</p>

      <div className="ax-row" style={{ gap: "var(--ax-space-150)", alignItems: "center", justifyContent: "center" }}>
        <button type="button" className="ax-btn ax-btn--subtle" onClick={() => setPage(p => Math.max(0, p - 1))} disabled={clampedPage === 0}>{strings.pagePrev}</button>
        <span className="ax-caption ax-numeric" role="status" aria-live="polite">
          {strings.pageStatus.replace("{a}", String(filtered.length === 0 ? 0 : clampedPage * PAGE_SIZE + 1)).replace("{b}", String(Math.min(filtered.length, (clampedPage + 1) * PAGE_SIZE))).replace("{n}", String(filtered.length))}
        </span>
        <button type="button" className="ax-btn ax-btn--subtle" onClick={() => setPage(p => Math.min(pageCount - 1, p + 1))} disabled={clampedPage >= pageCount - 1}>{strings.pageNext}</button>
      </div>

      {/* config — RELOCATES to P02 review step (increment 5); kept here so publish works */}
      <div className="ax-surface" style={{ padding: "var(--ax-space-300)", display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(200px,1fr))", gap: "var(--ax-space-200)" }}>
        <div className="ax-field"><label className="ax-field__label">{strings.visitType}</label>
          <select className="ax-select" name="visit_type"><option value="periodic">{strings.typePeriodic}</option></select></div>
        <div className="ax-field"><label className="ax-field__label">{strings.packageLabel}</label>
          <select className="ax-select" name="package_version_id">{packages.map(p => <option key={p.id} value={p.id}>{p.packages.code} · {p.version_label}</option>)}</select></div>
        <div className="ax-field"><label className="ax-field__label">{strings.windowStart}</label>
          <input key={resetKey} className="ax-input ax-numeric" name="window_start" type="datetime-local" required value={windowStart} onChange={e => setWindowStart(e.target.value)} /></div>
        <div className="ax-field"><label className="ax-field__label">{strings.windowEnd}</label>
          <input key={`e${resetKey}`} className="ax-input ax-numeric" name="window_end" type="datetime-local" required value={windowEnd} onChange={e => setWindowEnd(e.target.value)} /></div>
      </div>
      <div className="ax-surface" style={{ padding: "var(--ax-space-300)" }}>
        <div className="ax-field"><label className="ax-field__label">{strings.notes}</label>
          <textarea key={`n${resetKey}`} className="ax-textarea" name="notes" rows={2} placeholder={strings.notesPlaceholder} value={notes} onChange={e => setNotes(e.target.value)} /></div>
        <p className="ax-caption">{strings.assignmentNote}</p>
      </div>

      <div className="ax-surface" style={{ padding: "var(--ax-space-300)" }}>
        <h4 style={{ marginBlockEnd: "var(--ax-space-150)" }}>{strings.summaryTitle}</h4>
        {sel.length === 0 ? <p className="ax-caption">{strings.summaryEmpty}</p> : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(180px,1fr))", gap: "var(--ax-space-200)" }}>
            <div><span className="ax-caption">{strings.summarySelected}</span><div className="ax-numeric"><strong>{sel.length}</strong></div></div>
            <div><span className="ax-caption">{strings.summaryByBand}</span>
              <div className="ax-row" style={{ flexWrap: "wrap", gap: "var(--ax-space-100)" }}>
                {Object.entries(byBand).map(([b, n]) => <span key={b} className={`ax-lozenge ${b === "high" ? "ax-lozenge--critical" : b === "medium" ? "ax-lozenge--warning" : "ax-lozenge--success"}`}>{strings.riskBands[b] ?? b} · {n}</span>)}
              </div></div>
            <div><span className="ax-caption">{strings.summaryByRegion}</span>
              <div className="ax-row" style={{ flexWrap: "wrap", gap: "var(--ax-space-100)" }}>
                {Object.entries(byRegion).map(([r, n]) => <span key={r} className="ax-lozenge ax-lozenge--info"><bdi>{r}</bdi> · {n}</span>)}
              </div></div>
            <div><span className="ax-caption">{strings.summaryType}</span><div>{strings.typePeriodic}</div></div>
            <div><span className="ax-caption">{strings.summaryMode}</span><div>{strings.summaryModePhysical}</div></div>
          </div>
        )}
      </div>

      {state.error && <div className="ax-validation" role="alert"><strong>{strings.blockedTitle}</strong><ul>{state.error.split(" · ").map(b => <li key={b}>{b}</li>)}</ul></div>}

      {/* hidden selected ids submitted to the atomic publish action */}
      {[...selected].map(id => <input key={id} type="hidden" name="factory_id" value={id} />)}
      <label className="ax-choice" style={{ display: "flex", gap: "var(--ax-space-100)" }}>
        <input type="checkbox" name="skip_duplicates" value="1" checked={skipDuplicates} onChange={e => setSkipDuplicates(e.target.checked)} />
        <span>{strings.skipDuplicates}</span>
      </label>

      {/* persistent selection bar — cross-page count + readiness chips */}
      <div className="ax-surface ax-row" style={{ position: "sticky", insetBlockEnd: 0, padding: "var(--ax-space-200) var(--ax-space-300)", justifyContent: "space-between", flexWrap: "wrap", gap: "var(--ax-space-200)", alignItems: "center" }}>
        <div className="ax-row" style={{ gap: "var(--ax-space-150)", alignItems: "center", flexWrap: "wrap" }}>
          <strong className="ax-numeric" aria-live="polite">{strings.selectionBar.replace("{n}", String(selected.size))}</strong>
          {selected.size === 0 && <span className="ax-lozenge ax-lozenge--warning">⚠ {strings.readyNothing}</span>}
          <span className={`ax-lozenge ${packageValid ? "ax-lozenge--success" : "ax-lozenge--critical"}`}>{packageValid ? "✓" : "⛔"} {strings.readyPackage}</span>
          <span className={`ax-lozenge ${windowValid ? "ax-lozenge--success" : "ax-lozenge--warning"}`}>{windowValid ? "✓" : "⚠"} {strings.readyWindow}</span>
          {selected.size > 0 && <button type="button" className="ax-btn ax-btn--subtle" onClick={clearSelection}>{strings.clearSelection}</button>}
        </div>
        <button className="ax-btn ax-btn--prominent" disabled={pending || selected.size === 0}>{pending ? strings.publishing : strings.publish}</button>
      </div>
    </form>
  );
}

