tool_input.content:
"use server";
// CD-023 / SCR-WEB-130 — Immediate Visit Planning create+dispatch.
// Fixes confirmed runtime defects 1-5 (outputs/cd-023/IMPLEMENTATION_MANIFEST_CD-023.yaml):
//   1. region/city are now REQUIRED planner inputs on the temporary-factory path
//      (no more hardcoded region:"Riyadh"; no city was ever captured).
//   2. the assignments insert result is CHECKED — a failure returns the
//      structured ledger (visit exists, unassigned) instead of notifying/redirecting.
//   3. the 4 writes (temp factory, visit, assignment, notification) are not a
//      transaction (HANDOFF_BLOCKED — needs a Postgres RPC, a backend decision
//      not authorized here); a truthful step ledger is returned instead of
//      hiding the orphan-temp-factory possibility.
//   4. retry is keyed to already-created ids (resume_factory_id/resume_visit_id
//      hidden fields) so a resubmit never creates a second temp factory or visit;
//      an exact registered-CR match refuses temporary-entity creation (M02-012).
//   5. no raw error text reaches the client — failures are logged server-side
//      and returned as neutral, catalogued-tone copy.
import { redirect } from "next/navigation";
import { supabaseServer } from "@/lib/supabase-server";
import { insertNotification } from "@/lib/notify";

export type StepStatus = "done" | "failed" | "skipped" | "existing";
export type Ledger = { temp_factory: StepStatus; visit: StepStatus; assignment: StepStatus; notification: StepStatus };

export type ImmResult = {
  error?: string;
  blockingField?: "identity" | "location" | "reason" | "package" | "inspector" | "window";
  ledger?: Ledger;
  resumeFactoryId?: string;
  resumeVisitId?: string;
  visitId?: string;
  assignedName?: string;
  ok?: string;
};

// Internal errors are logged with this prefix and never forwarded verbatim to the UI.
function logInternal(step: string, e: unknown) {
  // eslint-disable-next-line no-console
  console.error(`[CD-023 immediate:${step}]`, e);
}
const NEUTRAL = {
  temp_factory: "Could not save the temporary factory record — a system error occurred. Your entered details are preserved; try again.",
  visit: "Could not create the visit record — a system error occurred. Your entered details are preserved; try again.",
  assignment: "Could not record the inspector assignment — a system error occurred.",
  notification: "Could not queue the assignment notification — a system error occurred.",
};

export async function createImmediateVisit(prev: ImmResult, formData: FormData): Promise<ImmResult> {
  const sb = await supabaseServer();
  const { data: { user } } = await sb.auth.getUser();
  if (!user) return { error: "Session expired." };

  const existing_factory_id = String(formData.get("existing_factory_id") ?? "");
  const manual_name = String(formData.get("manual_name") ?? "").trim();
  const manual_cr = String(formData.get("manual_cr") ?? "").trim();
  const manual_license = String(formData.get("manual_license") ?? "").trim();
  const manual_activity = String(formData.get("manual_activity") ?? "").trim();
  const manual_region = String(formData.get("manual_region") ?? "").trim();
  const manual_city = String(formData.get("manual_city") ?? "").trim();
  const lat = Number(formData.get("lat")); const lng = Number(formData.get("lng"));
  const reason = String(formData.get("urgency_reason") ?? "");
  const inspector_id = String(formData.get("inspector_id") ?? "");
  const package_version_id = String(formData.get("package_version_id") ?? "");
  const VISIT_TYPES = ["complaint", "follow_up", "periodic"];
  const visit_type = VISIT_TYPES.includes(String(formData.get("visit_type"))) ? String(formData.get("visit_type")) : "complaint";
  const priority = String(formData.get("priority") ?? "").trim();
  const notes = String(formData.get("notes") ?? "").trim();
  const wsRaw = String(formData.get("window_start") ?? "").trim();
  const weRaw = String(formData.get("window_end") ?? "").trim();
  const resume_factory_id = String(formData.get("resume_factory_id") ?? "").trim();
  const resume_visit_id = String(formData.get("resume_visit_id") ?? "").trim();
  const autoAssign = inspector_id === "auto" || inspector_id === "";

  // --- blockers (defect 1: region+city now required; M01-046 range-validated) ---
  const blockers: string[] = [];
  let blockingField: ImmResult["blockingField"] | undefined;
  const block = (msg: string, field: ImmResult["blockingField"]) => { blockers.push(msg); blockingField ??= field; };
  if (!existing_factory_id) {
    if (!manual_name) block("Factory identity required — name at minimum for unregistered (M01-045)", "identity");
    if (!manual_region) block("Region is required for a temporary factory entity (fixes prior hardcoded default)", "identity");
    if (!manual_city) block("City is required for a temporary factory entity", "identity");
  }
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    block("Location is mandatory before an Immediate Visit can be created (M01-046)", "location");
  } else if (lat < -90 || lat > 90 || lng < -180 || lng > 180) {
    block("Location coordinates are out of range (M01-046)", "location");
  }
  if (!reason) block("Urgency reason required (SCR-WEB-130)", "reason");
  if (!package_version_id) block("Published package required (ERR-PUB-001)", "package");
  let window_start: string; let window_end: string;
  if (!wsRaw && !weRaw) {
    const now = new Date(); window_start = now.toISOString(); window_end = new Date(now.getTime() + 8 * 3600e3).toISOString();
  } else {
    const s = new Date(wsRaw); const e = new Date(weRaw);
    if (!wsRaw || !weRaw || Number.isNaN(s.getTime()) || Number.isNaN(e.getTime())) {
      block("Provide both a valid window start and end, or leave both blank for the urgent default (M01-047)", "window");
      window_start = ""; window_end = "";
    } else if (e.getTime() <= s.getTime()) {
      block("Window end must be after window start (M01-047)", "window");
      window_start = ""; window_end = "";
    } else { window_start = s.toISOString(); window_end = e.toISOString(); }
  }

  // defect 4 (M02-012) — an exact registered CR match refuses temp-entity creation.
  if (!existing_factory_id && manual_cr) {
    const { data: crMatch } = await sb.from("factories").select("id, name").eq("is_temporary", false).eq("cr_number", manual_cr).maybeSingle();
    if (crMatch) block(`A registered factory already holds CR ${manual_cr} (${crMatch.name}) — search and select it instead of creating a temporary entity (M02-012)`, "identity");
  }
  if (blockers.length) return { error: blockers.join(" · "), blockingField, resumeFactoryId: resume_factory_id || undefined, resumeVisitId: resume_visit_id || undefined };

  // --- inspector pre-check (M01-048) — blocks before any write in the common case ---
  const { data: inspRows } = await sb.from("user_roles").select("user_id").eq("role_key", "inspector");
  const pool = (inspRows ?? []).map(r => r.user_id as string);
  if (pool.length === 0) return { error: "No eligible inspector in the pool (P02 failure control)", blockingField: "inspector" };
  const { data: overlaps } = await sb.from("assignments")
    .select("inspector_id, visits!inner(planning_status, window_start, window_end)")
    .in("inspector_id", autoAssign ? pool : [inspector_id])
    .in("visits.planning_status", ["draft", "published", "returned"])
    .lt("visits.window_start", window_end)
    .gt("visits.window_end", window_start);
  const booked = new Set((overlaps ?? []).map(o => o.inspector_id as string));
  if (!autoAssign) {
    if (!pool.includes(inspector_id)) return { error: "Selected inspector is not in the eligible pool (M01-048)", blockingField: "inspector" };
    if (booked.has(inspector_id)) return { error: "Selected inspector is already booked in this window — pick another or choose auto-assign (M01-048)", blockingField: "inspector" };
  } else if (!pool.some(id => !booked.has(id))) {
    return { error: "No inspector is available in this window — all are double-booked (M01-048)", blockingField: "inspector" };
  }

  // --- step 1: temp factory (skipped if registered; existing if resumed) ---
  const ledger: Ledger = { temp_factory: "skipped", visit: "failed", assignment: "failed", notification: "failed" };
  let factory_id = existing_factory_id;
  if (!factory_id && resume_factory_id) {
    const { data: f } = await sb.from("factories").select("id").eq("id", resume_factory_id).eq("is_temporary", true).maybeSingle();
    if (f) { factory_id = f.id; ledger.temp_factory = "existing"; }
  }
  if (!factory_id) {
    const { data: f, error } = await sb.from("factories").insert({
      name: manual_name, is_temporary: true, source: "immediate_manual",
      official_lat: lat, official_lng: lng, region: manual_region, city: manual_city,
      cr_number: manual_cr || null, license_number: manual_license || null,
      activity_class: manual_activity || null,
    }).select().single();
    if (error) { logInternal("temp_factory", error); return { error: NEUTRAL.temp_factory, ledger }; }
    factory_id = f.id; ledger.temp_factory = "done"; // flagged temporary entity (FLD-VIS-002)
  }

  // --- step 2: visit (existing if resumed) ---
  let visit_id = resume_visit_id;
  if (visit_id) {
    const { data: v } = await sb.from("visits").select("id").eq("id", visit_id).maybeSingle();
    if (v) ledger.visit = "existing"; else visit_id = "";
  }
  if (!visit_id) {
    const { data: visit, error: e2 } = await sb.from("visits").insert({
      visit_plan_id: null, // Immediate bypasses Visit Plans (M01-050)
      factory_id, visit_type, execution_mode: "physical",
      planning_status: "published", window_start, window_end,
      priority: priority || null,
      package_version_id, notes: notes ? `IMMEDIATE · ${reason} · ${notes}` : `IMMEDIATE · ${reason}`,
    }).select().single();
    if (e2) { logInternal("visit", e2); return { error: NEUTRAL.visit, ledger, resumeFactoryId: factory_id }; }
    visit_id = visit.id; ledger.visit = "done";
  }

  // --- step 3: assignment (existing if one already landed for this visit) ---
  const { data: existingAsg } = await sb.from("assignments").select("inspector_id").eq("visit_id", visit_id).maybeSingle();
  let assigned_id: string;
  if (existingAsg) {
    assigned_id = existingAsg.inspector_id; ledger.assignment = "existing"; // state 26 — discovered, not duplicated
  } else {
    const available = autoAssign ? pool.find(id => !booked.has(id)) : inspector_id;
    if (!available) {
      // race since the pre-check above: pool emptied concurrently.
      ledger.assignment = "failed";
      return { error: "No inspector is available — availability changed since the check above (M01-048)", ledger, resumeFactoryId: factory_id, resumeVisitId: visit_id, visitId: visit_id };
    }
    assigned_id = available;
    const { error: e3 } = await sb.from("assignments").insert({
      visit_id, inspector_id: assigned_id, method: autoAssign ? "automatic" : "manual",
      candidates: autoAssign ? { pool, chosen: assigned_id, reason: "first available in window" } : null,
    });
    if (e3) {
      logInternal("assignment", e3);
      // defect 2 fix: checked, not ignored — return the truthful ledger (visit exists, unassigned).
      return { error: NEUTRAL.assignment, ledger, resumeFactoryId: factory_id, resumeVisitId: visit_id, visitId: visit_id };
    }
    ledger.assignment = "done";
  }

  // --- step 4: notification (skip if one is already queued for this visit) ---
  const { data: existingNotif } = await sb.from("notifications").select("id").eq("event_key", "assignment").contains("payload", { visit_id }).maybeSingle();
  if (existingNotif) {
    ledger.notification = "existing";
  } else {
    const nr = await insertNotification(sb, { event_key: "assignment", recipient: assigned_id, payload: { visit_id, immediate: true }, channel: "push" });
    if (nr.error) { logInternal("notification", nr.error); ledger.notification = "failed"; }
    else ledger.notification = "done"; // queued — delivery not claimed (ENG-11)
  }

  redirect(`/visits/${visit_id}`);
}

