tool_input.content:
"use client";
// CD-023 (SCR-WEB-130, frames 3a/3g/3h/3i) — Minimum Viable Authority Bar.
// Nine protection chips derived ENTIRELY from ImmediateForm's existing
// validation state (no new policy objects). Chip states are glyph+text,
// never color alone (MVP1-FND-011): "satisfied" = evidence named, "blocking" =
// Enter jumps to the owning control, "truth" = an honest system statement that
// cannot be toggled (e.g. audit is always recorded; notification is always
// queued-not-delivered). This is never a progress meter or percentage — chips
// are independent, not sequential steps.
import { useEffect, useRef, useState } from "react";

export type ChipState = "satisfied" | "blocking" | "truth";
export type Chip = { id: string; label: string; state: ChipState; detail: string; controlId?: string };
export type AuthorityBarStrings = { groupLabel: string; satisfied: string; blocking: string; truth: string };

const GLYPH: Record<ChipState, string> = { satisfied: "✓", blocking: "✕", truth: "◌" };

export default function AuthorityBar({ chips, strings }: { chips: Chip[]; strings: AuthorityBarStrings }) {
  const [activeIdx, setActiveIdx] = useState(0);
  const btnRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const prevBlocking = useRef<string>("");
  const [announce, setAnnounce] = useState("");

  // Roving tabindex stays valid as chip count/order is stable across renders.
  useEffect(() => { if (activeIdx >= chips.length) setActiveIdx(0); }, [chips.length, activeIdx]);

  // Assertive announcement ONLY when the set of blocking chips actually
  // changes (not on every keystroke) — e.g. filling in the urgency reason
  // clears REASON from the blocking set.
  useEffect(() => {
    const blockingIds = chips.filter(c => c.state === "blocking").map(c => c.id).join(",");
    if (blockingIds !== prevBlocking.current) {
      const blocked = chips.filter(c => c.state === "blocking");
      setAnnounce(blocked.length === 0 ? "All protections satisfied" : blocked.map(c => `${c.label} blocking — ${c.detail}`).join(". "));
      prevBlocking.current = blockingIds;
    }
  }, [chips]);

  const focusChip = (idx: number) => { setActiveIdx(idx); btnRefs.current[idx]?.focus(); };
  const activate = (chip: Chip) => {
    if (!chip.controlId) return;
    const el = document.getElementById(chip.controlId);
    el?.focus();
    el?.scrollIntoView({ block: "center", behavior: "smooth" });
  };
  const onKeyDown = (e: React.KeyboardEvent, idx: number) => {
    const n = chips.length;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") { e.preventDefault(); focusChip((idx + 1) % n); }
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") { e.preventDefault(); focusChip((idx - 1 + n) % n); }
    else if (e.key === "Home") { e.preventDefault(); focusChip(0); }
    else if (e.key === "End") { e.preventDefault(); focusChip(n - 1); }
    else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); activate(chips[idx]); }
  };

  const firstBlocking = chips.find(c => c.state === "blocking");

  return (
    <div className="ax-authoritybar">
      <div className="ax-authoritybar__row" role="group" aria-label={strings.groupLabel}>
        {chips.map((chip, i) => (
          <button
            key={chip.id}
            type="button"
            ref={el => { btnRefs.current[i] = el; }}
            className={`ax-authoritybar__chip is-${chip.state}`}
            tabIndex={i === activeIdx ? 0 : -1}
            aria-label={`${chip.label} — ${chip.state === "satisfied" ? strings.satisfied : chip.state === "blocking" ? strings.blocking : strings.truth} — ${chip.detail}`}
            onFocus={() => setActiveIdx(i)}
            onClick={() => activate(chip)}
            onKeyDown={e => onKeyDown(e, i)}
          >
            <span className="ax-authoritybar__glyph" aria-hidden="true">{GLYPH[chip.state]}</span>
            <span className="ax-authoritybar__text">
              <bdi>{chip.label}</bdi>
              <span className="ax-authoritybar__detail">{chip.detail}</span>
            </span>
          </button>
        ))}
      </div>
      {/* Narrow-viewport companion (420px 9-dot strip): the currently-blocking
          chip's full text stays visible without requiring a tap on each dot. */}
      {firstBlocking && (
        <div className="ax-authoritybar__expanded ax-banner ax-banner--critical" role="status">
          <div><strong>{firstBlocking.label}</strong> — {firstBlocking.detail}</div>
        </div>
      )}
      <div className="ax-sr-only" role="alert" aria-live="assertive">{announce}</div>
    </div>
  );
}

tool_input.new_string:
.ax-stepper li.is-blocked .ax-step__dot { background: var(--ax-color-critical); color: var(--ax-color-inverse-text); }

/* Minimum Viable Authority Bar (CD-023 · SCR-WEB-130) — independent status
   chips, NOT a sequential stepper/progress meter: no connector arrows, no
   percentage. Glyph + text always both present (MVP1-FND-011). Amber is
   reserved for degraded truths, never used here as an emergency/red signal. */
.ax-authoritybar { display: flex; flex-direction: column; gap: var(--ax-space-100); }
.ax-authoritybar__row { display: flex; flex-wrap: wrap; gap: var(--ax-space-100); }
.ax-authoritybar__chip {
  display: flex; align-items: center; gap: var(--ax-space-100);
  min-block-size: var(--ax-control-height-prominent); padding: var(--ax-space-100) var(--ax-space-150);
  border: 1.5px solid var(--ax-color-border); border-radius: var(--ax-radius-standard);
  background: var(--ax-color-surface); color: var(--ax-color-text); cursor: pointer; text-align: start;
  transition: border-color var(--ax-motion-fast), background var(--ax-motion-fast);
}
.ax-authoritybar__chip:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }
.ax-authoritybar__glyph { font-size: 16px; line-height: 1; flex-shrink: 0; }
.ax-authoritybar__text { display: flex; flex-direction: column; gap: 2px; }
.ax-authoritybar__text > bdi { font: var(--ax-text-micro); letter-spacing: .04em; }
.ax-authoritybar__detail { font: var(--ax-text-caption); color: var(--ax-color-text-secondary); max-inline-size: 220px; }
.ax-authoritybar__chip.is-satisfied { border-color: color-mix(in srgb, var(--ax-color-success) 40%, var(--ax-color-border)); }
.ax-authoritybar__chip.is-satisfied .ax-authoritybar__glyph { color: var(--ax-color-success-strong); }
.ax-authoritybar__chip.is-blocking { border-color: color-mix(in srgb, var(--ax-color-critical) 45%, var(--ax-color-border)); background: var(--ax-color-critical-tint); }
.ax-authoritybar__chip.is-blocking .ax-authoritybar__glyph { color: var(--ax-color-critical-strong); }
.ax-authoritybar__chip.is-truth { border-style: dashed; border-color: var(--ax-color-border-strong); }
.ax-authoritybar__chip.is-truth .ax-authoritybar__glyph { color: var(--ax-color-warning-strong); }
.ax-authoritybar__expanded { display: none; }

@media (max-width: 560px) {
  .ax-authoritybar__chip { min-inline-size: var(--ax-control-height-prominent); padding: var(--ax-space-100); }
  .ax-authoritybar__text { display: none; }
  .ax-authoritybar__expanded { display: block; }
}

