      )}
    </form>
  );
}

import { test, expect, type Page } from "@playwright/test";
import { mkdirSync } from "node:fs";
import { join } from "node:path";
import { storageStatePath } from "./personas";
import { PERSONAS } from "./personas";
import { login, rest, must } from "./live-rest";

// CD-023 (SCR-WEB-130 /planning/immediate) — Minimum Viable Authority Bar.
// Requirements: M01-044/045 (identity), M01-046 (location mandatory, range),
// M01-047 (window/priority), M01-048 (availability + auto-assign audit),
// M01-050 (Immediate bypasses Visit Plans), M02-012 (duplicate/exact-CR
// refusal), FND-001 (RLS/no invented override), FND-003 (audit), FND-011
// (non-color-only). Acceptance: DSG-018, DSG-A11Y-001.
//
// Coverage note (honest gap, not silently dropped): the 3f step-ledger's
// mid-sequence DB-failure branches (temp-factory / visit / assignment /
// notification INSERT itself failing, as opposed to a pre-write validation
// blocker) are not exercisable from a black-box UI test without a
// fault-injection hook, which does not exist in this codebase. Those paths
// are covered by code review + TypeScript exhaustiveness in actions.ts, not
// by an automated browser assertion here. The one ledger branch that IS
// reachable without fault injection — the M01-048 availability race — is
// exercised below via a real double-booking.
const EVIDENCE_DIR = join(process.cwd(), "../../product-contract/evidence/screens/immediate-v2");

test.beforeAll(() => { mkdirSync(EVIDENCE_DIR, { recursive: true }); });

test.describe("CD-023 unauthorized state (frame 3e)", () => {
  test.use({ storageState: storageStatePath("inspector") });
  test("Inspector sees the no-data Planner-required state, not a redirect or override path", async ({ page }) => {
    await page.goto("/locale?set=en");
    await page.goto("/planning/immediate");
    await expect(page.getByRole("heading", { name: /Planner role required/i })).toBeVisible();
    await expect(page.getByText(/no specifically-authorized-inspector grant/i)).toBeVisible();
    // never a fabricated override control
    await expect(page.getByRole("button", { name: /override|authorize me/i })).toHaveCount(0);
  });
});

test.describe("CD-023 authority bar + form (Planner)", () => {
  test.use({ storageState: storageStatePath("planner") });

  test.beforeEach(async ({ page }) => { await page.goto("/locale?set=en"); });

  test("9 protection chips render, no coordinate prefill, roving-tabindex keyboard navigation, Enter jumps to owning control", async ({ page }) => {
    await page.goto("/planning/immediate");
    const group = page.getByRole("group", { name: /Immediate dispatch protections/i });
    await expect(group).toBeVisible();
    const chips = group.locator(".ax-authoritybar__chip");
    await expect(chips).toHaveCount(9);

    // MVP1-FND-011 — every chip carries a glyph, never color alone.
    for (const glyph of ["✓", "✕", "◌"]) {
      // at least the AUTHORIZED (✓) chip and a blocking (✕) chip and a truth (◌) chip must exist on first load
      await expect(group.locator(".ax-authoritybar__glyph", { hasText: glyph })).not.toHaveCount(0);
    }

    // No coordinate prefill (defect 7) — lat/lng start empty, not Riyadh center.
    await expect(page.locator("#imm-lat")).toHaveValue("");
    await expect(page.locator("#imm-lng")).toHaveValue("");

    // Roving tabindex: exactly one chip is tabbable at a time.
    await expect(chips).toHaveCount(9);
    const first = chips.first();
    await first.focus();
    await expect(first).toHaveAttribute("tabindex", "0");
    await page.keyboard.press("ArrowRight");
    const second = chips.nth(1);
    await expect(second).toHaveAttribute("tabindex", "0");
    await expect(first).toHaveAttribute("tabindex", "-1");

    // The REASON chip is blocking on first load (nothing selected yet) —
    // Enter must jump focus to the reason control group.
    const reasonChip = group.locator(".ax-authoritybar__chip", { hasText: "REASON" });
    await reasonChip.focus();
    await page.keyboard.press("Enter");
    await expect(page.locator("#imm-reason")).toBeFocused();

    await page.screenshot({ path: join(EVIDENCE_DIR, "primary-en-dark.png"), fullPage: true });
  });

  test("temporary path requires region + city (defect 1) and preserves entered work on a blocked submit (defect 6)", async ({ page }) => {
    await page.goto("/planning/immediate");
    await page.getByRole("button", { name: "Unregistered / temporary" }).click();
    await page.locator("#imm-manual-name").fill("CD-023 Playwright Temp Factory");
    // Deliberately leave region/city blank — submit should block, not create.
    await page.locator("#imm-priority").fill("keep-this-text");
    await page.getByRole("button", { name: /Create & dispatch/i }).click();
    await expect(page.getByText(/Region is required for a temporary factory entity/i)).toBeVisible();
    await expect(page.getByText(/City is required for a temporary factory entity/i)).toBeVisible();
    // work preservation — the already-typed values are still there after the blocked round-trip.
    await expect(page.locator("#imm-manual-name")).toHaveValue("CD-023 Playwright Temp Factory");
    await expect(page.locator("#imm-priority")).toHaveValue("keep-this-text");
    // no raw db/provider text ever reaches the DOM
    await expect(page.locator("body")).not.toContainText(/PGRST|duplicate key value|violates/i);
  });

  test("exact registered CR match refuses temporary-entity creation (M02-012)", async ({ page }) => {
    const planner = await login(PERSONAS.planner.email, PERSONAS.planner.password);
    const code = `CD023-CR-${Date.now()}`;
    const cr = `CD023-${Date.now() % 1000000}`;
    const registered = must(await rest("POST", "factories", planner.jwt, {
      factory_code: code, name: `CD-023 Registered Fixture ${code}`,
      cr_number: cr, region: "Riyadh", city: "Riyadh", is_temporary: false,
      official_lat: 24.7136, official_lng: 46.6753, risk_band: "low", risk_score: 5,
    }), "create registered fixture")[0];
    expect(registered.id).toBeTruthy();

    await page.goto("/planning/immediate");
    await page.getByRole("button", { name: "Unregistered / temporary" }).click();
    await page.locator("#imm-manual-name").fill("Attempted duplicate temp entity");
    await page.locator("#imm-manual-cr").fill(cr);
    await page.locator("#imm-manual-region").fill("Riyadh");
    await page.locator("#imm-manual-city").fill("Riyadh");
    await page.getByRole("button", { name: /Complaint received/i }).click();
    await page.locator("#imm-lat").fill("24.7136");
    await page.locator("#imm-lng").fill("46.6753");
    await page.getByRole("button", { name: /Create & dispatch/i }).click();
    await expect(page.getByText(/already holds CR/i)).toBeVisible();
    // no ledger/step panel — nothing was created
    await expect(page.getByText(/Dispatch step ledger/i)).toHaveCount(0);
  });

  test("full success: create & dispatch a temporary-entity immediate visit (M01-050, M01-048 auto-assign, ENG-12 audit)", async ({ page }) => {
    const code = `CD023-IMM-${Date.now()}`;
    await page.goto("/planning/immediate");
    await page.getByRole("button", { name: "Unregistered / temporary" }).click();
    await page.locator("#imm-manual-name").fill(`CD-023 Immediate ${code}`);
    await page.locator("#imm-manual-region").fill("Riyadh");
    await page.locator("#imm-manual-city").fill("Riyadh");
    await page.getByRole("button", { name: /Incident report/i }).click();
    await page.locator("#imm-lat").fill("24.71");
    await page.locator("#imm-lng").fill("46.67");
    await page.getByRole("button", { name: /Create & dispatch/i }).click();
    await page.waitForURL(/\/visits\/[0-9a-f-]+/, { timeout: 15_000 });

    const visitId = page.url().split("/visits/")[1];
    const planner = await login(PERSONAS.planner.email, PERSONAS.planner.password);
    const [visit] = must(await rest("GET", `visits?id=eq.${visitId}&select=id,visit_plan_id,planning_status,execution_mode`, planner.jwt), "read created visit");
    expect(visit.visit_plan_id).toBeNull(); // M01-050 — Immediate bypasses Visit Plans
    expect(visit.planning_status).toBe("published");
    const [asg] = must(await rest("GET", `assignments?visit_id=eq.${visitId}&select=inspector_id,method,candidates`, planner.jwt), "read assignment");
    expect(asg.inspector_id).toBeTruthy();
    expect(asg.method).toBe("automatic");
    expect(asg.candidates?.pool?.length).toBeGreaterThan(0); // M01-048 candidate pool audited
    const notifs = must(await rest("GET", `notifications?event_key=eq.assignment&payload->>visit_id=eq.${visitId}`, planner.jwt), "read notification");
    expect(notifs.length).toBeGreaterThan(0); // queued — delivery never claimed (ENG-11)
  });

  test("manually-picked inspector already booked in the same window is blocked, not silently reassigned (M01-048)", async ({ page }) => {
    const planner = await login(PERSONAS.planner.email, PERSONAS.planner.password);
    const inspector = await login(PERSONAS.inspector.email, PERSONAS.inspector.password);
    const start = new Date(Date.now() + 3600e3).toISOString();
    const end = new Date(Date.now() + 2 * 3600e3).toISOString();
    // Book the seeded inspector persona directly via REST for a known window.
    const factory = must(await rest("POST", "factories", planner.jwt, {
      factory_code: `CD023-BOOK-${Date.now()}`, name: `CD-023 Booking Fixture ${Date.now()}`,
      cr_number: `CD023B-${Date.now() % 1000000}`, region: "Riyadh", city: "Riyadh", is_temporary: false,
      official_lat: 24.7136, official_lng: 46.6753,
    }), "create booking fixture factory")[0];
    const pkg = must(await rest("GET", "package_versions?select=id&status=eq.published&limit=1", planner.jwt), "package")[0];
    const [visit] = must(await rest("POST", "visits", planner.jwt, {
      factory_id: factory.id, visit_type: "complaint", execution_mode: "physical",
      planning_status: "published", window_start: start, window_end: end, package_version_id: pkg.id,
    }), "create pre-booking visit");
    await rest("POST", "assignments", planner.jwt, { visit_id: visit.id, inspector_id: inspector.userId, method: "manual" }, "return=minimal");

    await page.goto("/planning/immediate");
    await page.getByRole("button", { name: "Unregistered / temporary" }).click();
    await page.locator("#imm-manual-name").fill(`CD-023 Conflict Attempt ${Date.now()}`);
    await page.locator("#imm-manual-region").fill("Riyadh");
    await page.locator("#imm-manual-city").fill("Riyadh");
    await page.getByRole("button", { name: /Complaint received/i }).click();
    await page.locator("#imm-lat").fill("24.7136");
    await page.locator("#imm-lng").fill("46.6753");
    await page.locator("#imm-window-start").fill(start.slice(0, 16));
    await page.locator("#imm-window-end").fill(end.slice(0, 16));
    await page.locator("#imm-inspector").selectOption(inspector.userId);
    await page.getByRole("button", { name: /Create & dispatch/i }).click();
    await expect(page.getByText(/already booked in this window/i)).toBeVisible();
  });
});

test.describe("CD-023 visual evidence — narrow + Arabic RTL", () => {
