export const dynamic = "force-dynamic";

// CD-022 — server-side identifier + name search (name search is NEW; the
// prior runtime only matched CR/factory_code/license_number client-side over
// the full table). EXACT = governed identifier equality only (no scoring).
// SIMILAR NAME = the search term matched the entity's name, not any
// identifier — the differing identifier is always returned so the planner
// sees exactly what distinguishes the candidate. A query that matches
// neither exactly nor by name is not returned: partial/fuzzy identifier
// matching is deliberately not offered — identifiers are precise codes, and
// a coincidental substring match on a CR/license number is not a safe
// candidate to surface silently.
function gradeCandidate(f: { cr_number: string | null; factory_code: string | null; license_number: string | null; name: string }, q: string): "exact" | "similar_name" | null {
  const ql = q.toLowerCase();
  const identifierExact =
    (f.cr_number != null && f.cr_number === q) ||
    (f.factory_code != null && f.factory_code.toLowerCase() === ql) ||
    (f.license_number != null && f.license_number.toLowerCase() === ql);
  if (identifierExact) return "exact";
  if (f.name.toLowerCase().includes(ql)) return "similar_name";
  return null;
}

export default async function SinglePlanning({ searchParams }: { searchParams: Promise<{ q?: string }> }) {
  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const searching = q.length >= 3;
  const { t } = await useT();
  const sb = await supabaseServer();

  const [{ data: pkgs }, { data: inspRoles }, { data: otpEngine }] = await Promise.all([
    sb.from("package_versions").select("id, version_label, packages(code, title)").in("status", ["published", "locked"]).order("published_at", { ascending: false }),
    sb.from("user_roles").select("user_id, profiles!user_roles_user_id_fkey(full_name)").eq("role_key", "inspector"),
    sb.from("engine_settings").select("engine").eq("engine", "otp").maybeSingle(),
  ]);
  const inspectors = (inspRoles ?? []).map(r => ({ user_id: r.user_id, full_name: (r.profiles as unknown as { full_name: string }).full_name }));
  const virtualEligible = !!otpEngine;

  // Server-side search: a broad DB-side ilike/eq net across the four
  // identifier+name fields (RLS-scoped, no service-role bypass), narrowed to
  // the precise EXACT/SIMILAR-NAME rule in JS afterward. Replaces the prior
  // client-side filter over the entire unpaginated factories table.
  let graded: GradedFactory[] = [];
  if (searching) {
    const esc = q.replace(/[%_]/g, c => `\\${c}`);
    const { data: candidates } = await sb.from("factories")
      .select("id, factory_code, name, cr_number, license_number, region, city, risk_band, risk_score, official_lat, official_lng, geofence_radius_m, source_synced_at")
      .or(`cr_number.eq.${q},factory_code.ilike.%${esc}%,license_number.ilike.%${esc}%,name.ilike.%${esc}%`)
      .limit(50);
    const dupChecks = await Promise.all((candidates ?? []).map(f => findDuplicateActiveVisits(sb, f.id)));
    graded = (candidates ?? [])
      .map((f, i) => ({ f, grade: gradeCandidate(f, q), dups: dupChecks[i] }))
      .filter((r): r is { f: NonNullable<typeof candidates>[number]; grade: "exact" | "similar_name"; dups: Awaited<ReturnType<typeof findDuplicateActiveVisits>> } => r.grade !== null)
      .map(({ f, grade, dups }) => ({
        id: f.id, factory_code: f.factory_code, name: f.name, cr_number: f.cr_number, license_number: f.license_number,
        region: f.region, city: f.city, risk_band: f.risk_band, risk_score: f.risk_score,
        official_lat: f.official_lat, official_lng: f.official_lng, geofence_radius_m: f.geofence_radius_m,
        source_synced_at: (f as unknown as { source_synced_at: string | null }).source_synced_at,
        grade,
        degraded: !f.license_number || f.official_lat == null || f.official_lng == null,
        duplicate: dups.length > 0,
        duplicateVisitId: dups[0]?.id ?? null,
      }));
  }

  const strings: WizardStrings = {
    findFactory: t("plan.single.findFactory", "1 · Find factory — CR, code, Industrial License or name (M01-035)"),
    searchPlaceholder: t("plan.single.searchPlaceholder", "CR number, factory code, Industrial License or name"),
    noMatch: t("plan.single.noMatch", "No factory matches — check the number, or create an Immediate Visit (M01-045)."),
    crPrefix: t("plan.single.crPrefix", "CR"),
    exactBadge: t("plan.single.exactBadge", "EXACT"),
    exactRule: t("plan.single.exactRule", "Matches a governed identifier exactly (CR, factory code or Industrial License)"),
    similarBadge: t("plan.single.similarBadge", "SIMILAR NAME"),
    similarRule: t("plan.single.similarRule", "Name matches — identifiers differ from your search"),
    degradedBadge: t("plan.single.degradedBadge", "DEGRADED RECORD"),
    degradedRule: t("plan.single.degradedRule", "Missing Industrial License or official coordinates"),
    duplicateWarning: t("plan.single.duplicateWarning", "An active visit already exists for this factory (M02-012) — shown as a warning here, blocked at publish"),
    licenseStep: t("plan.single.licenseStep", "2 · Industrial License (M01-036)"),
    licenseSelect: t("plan.single.licenseSelect", "Select the Industrial License this visit is planned against"),
    licenseLabel: t("plan.single.licenseLabel", "Industrial license"),
    licenseNone: t("plan.single.licenseNone", "No Industrial License on record for this factory — the visit proceeds against the CR (M01-036)."),
    locationStep: t("plan.single.locationStep", "3 · Confirm location (M01-038)"),
    officialPin: t("plan.single.officialPin", "Official factory pin"),
    noOfficialPin: t("plan.single.noOfficialPin", "No official location on record — pin the visit location manually below."),
    plannerLat: t("plan.single.plannerLat", "Planner pin latitude (optional override)"),
    plannerLng: t("plan.single.plannerLng", "Planner pin longitude (optional override)"),
    plannerPin: t("plan.single.plannerPin", "Planner pin (this visit only — official pin is GIS Admin owned)"),
    locationConfirmed: t("plan.single.locationConfirmed", "Location confirmed — publish is blocked until confirmed (M01-038)"),
    mapLoading: t("plan.single.mapLoading", "Loading location map"),
    mapToggle: t("plan.single.mapToggle", "Map / Text"),
    textEquivalent: t("plan.single.textEquivalent", "Text equivalent of the location map"),
    riskContext: t("plan.single.riskContext", "Risk context (ENG-04 v1 · advisory — never drives selection)"),
    riskUnknown: t("plan.single.riskUnknown", "not recorded"),
    freshnessLabel: t("plan.single.freshnessLabel", "Registry sync"),
    freshnessNever: t("plan.single.freshnessNever", "no sync record"),
    factory360: t("plan.single.factory360", "Open Factory 360"),
    configStep: t("plan.single.configStep", "4 · Configure & assign"),
    visitType: t("plan.single.visitType", "Visit type"),
    typePeriodic: t("enum.periodic", "Periodic compliance"),
    typeFollowUp: t("enum.follow_up", "Follow-up"),
    typeComplaint: t("enum.complaint", "Complaint-triggered"),
    packageLabel: t("plan.single.package", "Package (published only)"),
    mode: t("plan.single.mode", "Mode"),
    modePhysical: t("enum.physical", "Physical"),
    modeVirtual: t("enum.virtual", "Virtual"),
    modeIneligible: t("plan.single.modeIneligible", "not eligible (M03-011)"),
    windowStart: t("plan.single.windowStart", "Window start"),
    windowEnd: t("plan.single.windowEnd", "Window end"),
    inspector: t("plan.single.inspector", "Inspector (M01-040)"),
    selectOption: t("plan.single.select", "— select"),
    autoAssign: t("plan.single.autoAssign", "Auto-assign — first available inspector (M01-040)"),
    notes: t("plan.single.notes", "Notes (optional)"),
    notesPlaceholder: t("plan.single.notesPlaceholder", "Anything the inspector or reviewer should know before this visit…"),
    readinessTitle: t("plan.single.readinessTitle", "Readiness"),
    readyIdentity: t("plan.single.readyIdentity", "Identity confirmed"),
    readyLicense: t("plan.single.readyLicense", "License confirmed"),
    readyLocation: t("plan.single.readyLocation", "Location confirmed"),
    readyInspector: t("plan.single.readyInspector", "Inspector ready"),
    blockedTitle: t("plan.single.blocked", "Publishing blocked — work preserved (M01-041)"),
    publish: t("plan.single.publish", "Publish visit (one plan · one visit — M01-042)"),
    publishing: t("plan.single.publishing", "Publishing…"),
    retry: t("plan.single.retry", "Retry — resumes safely, will not duplicate"),
    stepPlan: t("plan.single.stepPlan", "Plan created"),
    stepVisit: t("plan.single.stepVisit", "Visit created"),
    stepAssignment: t("plan.single.stepAssignment", "Inspector assigned"),
    stepStatus: t("plan.single.stepStatus", "Published"),
    stepNotification: t("plan.single.stepNotification", "Notification queued"),
    stepDone: t("plan.single.stepDone", "done"),
    stepFailed: t("plan.single.stepFailed", "failed"),
    stepPending: t("plan.single.stepPending", "not attempted"),
    riskBands: {
      high: t("enum.high", "high"),
      medium: t("enum.medium", "medium"),
      low: t("enum.low", "low"),
    },
  };
  return (
    <Shell current="/planning" title={t("plan.single.title", "Single visit planning")}
      context={<span className="ax-lozenge ax-lozenge--info">{t("plan.single.context", "SCR-WEB-120 · identity confidence lens")}</span>}>
      <Wizard query={q} results={graded} packages={(pkgs ?? []) as never} inspectors={inspectors} strings={strings} virtualEligible={virtualEligible} />
    </Shell>
  );
}

"use client";
// CD-022 — Identity dossier: identifier grid + provenance + official/planner
// location (map with mandatory text equivalent) + risk context (advisory
// only) + duplicate/overlap guard + Factory 360 deep link. Composed inside
// the comparison rail in Wizard.tsx; nothing here mutates the registry —
// the planner pin is per-visit only (M01-038).
import { useState } from "react";
import dynamic from "next/dynamic";
import type { GeoMarkerData } from "@/components/GeoMap";
import type { GradedFactory, WizardStrings } from "./Wizard";

const GeoMap = dynamic(() => import("@/components/GeoMap"), { ssr: false });

export default function IdentityDossier({
  factory, plannerLat, plannerLng, strings,
}: {
  factory: GradedFactory; plannerLat: string; plannerLng: string; strings: WizardStrings;
}) {
  const [view, setView] = useState<"map" | "text">("map");
  const hasOfficial = factory.official_lat != null && factory.official_lng != null;
  const pLat = Number(plannerLat); const pLng = Number(plannerLng);
  const hasPlannerPin = plannerLat !== "" && plannerLng !== "" && Number.isFinite(pLat) && Number.isFinite(pLng);
  const markers: GeoMarkerData[] = [
    ...(hasOfficial ? [{
      id: "official", lat: factory.official_lat as number, lng: factory.official_lng as number,
      label: `${strings.officialPin} — ${factory.name}`,
      tone: (factory.risk_band === "high" ? "high" : factory.risk_band === "medium" ? "medium" : "low") as GeoMarkerData["tone"],
      radiusM: factory.geofence_radius_m ?? undefined,
    }] : []),
    ...(hasPlannerPin ? [{ id: "planner", lat: pLat, lng: pLng, label: strings.plannerPin, tone: "neutral" as const }] : []),
  ];
  const center: [number, number] = hasOfficial
    ? [factory.official_lat as number, factory.official_lng as number]
    : hasPlannerPin ? [pLat, pLng] : [24.7136, 46.6753];

  return (
    <div className="ax-surface" style={{ padding: "var(--ax-space-300)", display: "flex", flexDirection: "column", gap: "var(--ax-space-200)" }} role="region" aria-label={factory.name}>
      <div>
        <strong style={{ fontSize: "var(--ax-font-size-150)" }}>{factory.name}</strong>
        {factory.grade === "exact"
          ? <span className="ax-lozenge ax-lozenge--success" style={{ marginInlineStart: 8 }}>{strings.exactBadge}</span>
          : <span className="ax-lozenge ax-lozenge--warning" style={{ marginInlineStart: 8 }}>{strings.similarBadge}</span>}
        {factory.degraded && <span className="ax-lozenge ax-lozenge--critical" style={{ marginInlineStart: 8 }}>{strings.degradedBadge}</span>}
        <p className="ax-caption">{factory.grade === "exact" ? strings.exactRule : strings.similarRule}</p>
      </div>

      {/* Identifier grid — bdi-isolated so LTR codes read correctly inside Arabic labels */}
      <dl className="ax-grid-2" style={{ rowGap: "var(--ax-space-100)" }}>
        <div><dt className="ax-caption">{strings.crPrefix}</dt><dd><bdi>{factory.cr_number ?? "—"}</bdi></dd></div>
        <div><dt className="ax-caption">{strings.licenseLabel}</dt><dd><bdi>{factory.license_number ?? strings.licenseNone}</bdi></dd></div>
        <div><dt className="ax-caption">{strings.factory360}</dt><dd><bdi>{factory.factory_code ?? "—"}</bdi></dd></div>
        <div><dt className="ax-caption">{factory.region ?? "—"}{factory.city ? `, ${factory.city}` : ""}</dt></div>
      </dl>

      {/* Provenance — real FND-013 freshness; no invented staleness threshold */}
      <p className="ax-caption">{strings.freshnessLabel}: <bdi>{factory.source_synced_at ? new Date(factory.source_synced_at).toISOString().slice(0, 10) : strings.freshnessNever}</bdi></p>

      {factory.duplicate && (
        <div className="ax-banner ax-banner--warning" role="status"><div>{strings.duplicateWarning}</div></div>
      )}

      <div>
        <div className="ax-segmented" role="group" aria-label={strings.mapToggle}>
          <button type="button" aria-pressed={view === "map"} onClick={() => setView("map")}>{strings.mapToggle.split(" / ")[0]}</button>
          <button type="button" aria-pressed={view === "text"} onClick={() => setView("text")}>{strings.mapToggle.split(" / ")[1]}</button>
        </div>
        {view === "map" ? (
          <div style={{ blockSize: 220, marginBlockStart: "var(--ax-space-150)" }}>
            <GeoMap center={center} zoom={hasOfficial || hasPlannerPin ? 14 : 6} markers={markers} height="100%" />
          </div>
        ) : (
          <ul className="ax-caption" style={{ marginBlockStart: "var(--ax-space-150)" }} aria-label={strings.textEquivalent}>
            <li>{strings.officialPin}: {hasOfficial ? <bdi>{factory.official_lat}, {factory.official_lng}</bdi> : strings.noOfficialPin}</li>
            {hasPlannerPin && <li>{strings.plannerPin}: <bdi>{plannerLat}, {plannerLng}</bdi></li>}
          </ul>
        )}
      </div>

      <p className="ax-caption">{strings.riskContext}: {factory.risk_band ?? strings.riskUnknown}{factory.risk_score != null ? ` (${factory.risk_score})` : ""}</p>

      <a href={`/factories/${factory.id}`} target="_blank" rel="noopener noreferrer" className="ax-btn ax-btn--secondary">{strings.factory360}</a>
    </div>
  );
}

"use server";
import { redirect } from "next/navigation";
import { supabaseServer } from "@/lib/supabase-server";
import { findDuplicateActiveVisits } from "./duplicate";

export type StepStatus = "pending" | "done" | "failed";
export type PublishSteps = { plan: StepStatus; visit: StepStatus; assignment: StepStatus; status: StepStatus; notification: StepStatus };
export type PublishResult = { error?: string; steps?: PublishSteps; resumeId?: string };

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

// CD-022 — catalogued neutral copy for write-phase failures. Raw Supabase
// error text must never reach the UI (schema/internal detail leak); the real
// cause is logged server-side only. Validation blockers below are deliberate
// governed business messages, not raw provider errors, and are unchanged.
const NEUTRAL_WRITE_ERROR =
  "Publishing could not complete a step. Your entries are preserved — review the step status below and retry; retry will not create a second visit.";

export async function publishSingleVisit(_: PublishResult, formData: FormData): Promise<PublishResult> {
  const sb = await supabaseServer();
  const { data: { user } } = await sb.auth.getUser();
  if (!user) return { error: "Session expired — sign in again." };

  const factory_id = String(formData.get("factory_id") ?? "");
  const package_version_id = String(formData.get("package_version_id") ?? "");
  const inspector_id = String(formData.get("inspector_id") ?? "");
  const visit_type = String(formData.get("visit_type") ?? "periodic");
  const window_start = String(formData.get("window_start") ?? "");
  const window_end = String(formData.get("window_end") ?? "");
  const mode = String(formData.get("execution_mode") ?? "physical");
  const license_number = String(formData.get("license_number") ?? "");
  const location_confirmed = formData.get("location_confirmed") === "1";
  const plannerLatRaw = String(formData.get("planner_lat") ?? "").trim();
  const plannerLngRaw = String(formData.get("planner_lng") ?? "").trim();
  const planner_lat = plannerLatRaw === "" ? null : Number(plannerLatRaw);
  const planner_lng = plannerLngRaw === "" ? null : Number(plannerLngRaw);
  const notesRaw = String(formData.get("notes") ?? "").trim();
  const notes = notesRaw === "" ? null : notesRaw;
  const resumeRaw = String(formData.get("resume_visit_plan_id") ?? "").trim();
  const resumeId = UUID.test(resumeRaw) ? resumeRaw : "";

  // Publish validation gate (M01-041) — exact blockers, work preserved.
  // Unchanged from the prior runtime.
  const blockers: string[] = [];
  if (!factory_id) blockers.push("Factory not selected (M01-035)");
  if (factory_id) {
    // License + location gates validated against the factory record (M01-036 / M01-038)
    const { data: fac } = await sb.from("factories")
      .select("license_number, official_lat, official_lng").eq("id", factory_id).single();
    if (fac?.license_number && license_number !== fac.license_number)
      blockers.push("Industrial License must be selected and confirmed before publish (M01-036)");
    const hasPlannerPin = planner_lat != null && planner_lng != null && Number.isFinite(planner_lat) && Number.isFinite(planner_lng);
    if ((planner_lat != null || planner_lng != null) && !hasPlannerPin)
      blockers.push("Planner pin needs both a valid latitude and longitude (M01-038)");
    const hasOfficial = fac?.official_lat != null && fac?.official_lng != null;
    if (fac && !hasOfficial && !hasPlannerPin)
      blockers.push("No official location on record — pin the visit location manually (M01-038)");
    // Execution-mode eligibility (M03-011): physical needs GIS-verifiable
    // coordinates, virtual needs the OTP engine configured. Startup.tsx
    // already computes and displays this read-only after publish — this is
    // the only place mode is actually chosen, so it's the only place that
    // can enforce "an ineligible mode cannot be selected" for real.
    if (mode === "physical" && !hasOfficial && !hasPlannerPin)
      blockers.push("Physical execution needs a GIS-verifiable location — no official pin and none provided (M03-011)");
    if (mode === "virtual") {
      const { data: otpEngine } = await sb.from("engine_settings").select("engine").eq("engine", "otp").maybeSingle();
      if (!otpEngine) blockers.push("Virtual execution requires the OTP engine to be configured (M03-011)");
    }
  }
  if (!location_confirmed) blockers.push("Location must be confirmed on the map before publish (M01-038)");
  if (!package_version_id) blockers.push("No published package selected (ERR-PUB-001)");
  // M01-040 — either a manual inspector or the auto-assign option ("auto") is required.
  const autoAssign = inspector_id === "auto";
  if (!inspector_id) blockers.push("Assign an inspector or choose auto-assign before publish (M01-040)");
  if (!window_start || !window_end || new Date(window_end) <= new Date(window_start))
    blockers.push("Visit window end must be after start (FLD-PLAN-005)");
  // Duplicate active visit (M02-012) — same shared check the dossier surfaces
  // as a selection-time warning; here it remains the hard publish-time block.
  if (factory_id) {
    const dups = await findDuplicateActiveVisits(sb, factory_id, visit_type);
    if (dups.length > 0) blockers.push(`Duplicate active visit exists for this factory/type (M02-012): ${dups[0].id.slice(0, 8)}`);
  }
  if (blockers.length) return { error: blockers.join(" · ") };

  // M01-040 — resolve the inspector with an availability check: auto-assign the
  // first inspector with no overlapping active assignment in this window, or
  // validate the manual pick's availability (no double-booking).
  const { data: inspRows } = await sb.from("user_roles").select("user_id").eq("role_key", "inspector");
  const pool = (inspRows ?? []).map(r => r.user_id as string);
  if (pool.length === 0) return { error: "No eligible inspector in the pool (M01-040 / P02)" };
  const { data: overlaps } = await sb.from("assignments")
    .select("inspector_id, visits!inner(planning_status, window_start, window_end)")
    .in("inspector_id", autoAssign ? pool : [inspector_id])
    .in("visits.planning_status", ["draft", "published", "returned"])
    .lt("visits.window_start", window_end)
    .gt("visits.window_end", window_start);
  const booked = new Set((overlaps ?? []).map(o => o.inspector_id as string));
  let assigned_id: string; let assign_method: "manual" | "automatic";
  if (autoAssign) {
    const available = pool.find(pid => !booked.has(pid));
    if (!available) return { error: "No inspector is available in this window — all are double-booked (M01-040)" };
    assigned_id = available; assign_method = "automatic";
  } else {
    if (!pool.includes(inspector_id)) return { error: "Selected inspector is not in the eligible pool (M01-040)" };
    if (booked.has(inspector_id)) return { error: "Selected inspector is already booked in this window — pick another or choose auto-assign (M01-040)" };
    assigned_id = inspector_id; assign_method = "manual";
  }

  const steps: PublishSteps = { plan: "pending", visit: "pending", assignment: "pending", status: "pending", notification: "pending" };

  // CD-022 — resumable retry keyed by visit_plan_id. If resumeId is present it
  // must resolve to a plan this user owns; a resumeId that fails to resolve
  // fails closed (neutral copy) rather than silently falling through to a
  // fresh insert, so retry can never create a second visit.
  let planId: string;
  if (resumeId) {
    const { data: plan } = await sb.from("visit_plans").select("id").eq("id", resumeId).eq("created_by", user.id).eq("method", "single").maybeSingle();
    if (!plan) return { error: NEUTRAL_WRITE_ERROR, steps };
    planId = plan.id; steps.plan = "done";
  } else {
    const { data: plan, error: e1 } = await sb.from("visit_plans")
      .insert({ method: "single", status: "draft", created_by: user.id }).select().single();
    if (e1 || !plan) {
      console.error("[CD-022 publishSingleVisit] plan insert failed:", e1?.message);
      steps.plan = "failed";
      return { error: NEUTRAL_WRITE_ERROR, steps };
    }
    planId = plan.id; steps.plan = "done";
  }

  let visitId: string;
  {
    const { data: existingVisit } = await sb.from("visits").select("id").eq("visit_plan_id", planId).maybeSingle();
    if (existingVisit) {
      visitId = existingVisit.id; steps.visit = "done";
    } else {
      const { data: visit, error: e2 } = await sb.from("visits").insert({
        visit_plan_id: planId, factory_id, visit_type, execution_mode: mode,
        planning_status: "draft", window_start, window_end, package_version_id,
        // planner pin ≠ official pin (M01-038) — only stored when the planner overrode it
        planner_lat: planner_lat != null && Number.isFinite(planner_lat) ? planner_lat : null,
        planner_lng: planner_lng != null && Number.isFinite(planner_lng) ? planner_lng : null,
        notes,
      }).select().single();
      if (e2 || !visit) {
        console.error("[CD-022 publishSingleVisit] visit insert failed:", e2?.message);
        steps.visit = "failed";
        return { error: NEUTRAL_WRITE_ERROR, steps, resumeId: planId };
      }
      visitId = visit.id; steps.visit = "done";
    }
  }

  {
    const { data: existingAssignment } = await sb.from("assignments").select("id").eq("visit_id", visitId).maybeSingle();
    if (existingAssignment) {
      steps.assignment = "done";
    } else {
      const { error: e3 } = await sb.from("assignments").insert({
        visit_id: visitId, inspector_id: assigned_id, method: assign_method,
        candidates: assign_method === "automatic" ? { pool, chosen: assigned_id, reason: "first available in window" } : null,
      });
      if (e3) {
        console.error("[CD-022 publishSingleVisit] assignment insert failed:", e3.message);
        steps.assignment = "failed";
        return { error: NEUTRAL_WRITE_ERROR, steps, resumeId: planId };
      }
      steps.assignment = "done";
    }
  }

  {
    const { data: visitRow } = await sb.from("visits").select("planning_status").eq("id", visitId).single();
    const { data: planRow } = await sb.from("visit_plans").select("status").eq("id", planId).single();
    if (visitRow?.planning_status === "published" && planRow?.status === "published") {
      steps.status = "done";
    } else {
      // Atomic publish step (STM-PLAN-002 side effects; notification row = ENG-11).
      // Atomicity across the two updates above is HANDOFF_BLOCKED (no
      // transaction/RPC exists for this screen) — this is the truthful step
      // ledger over sequential writes, not a claim of atomicity.
      const { error: e4 } = await sb.from("visits").update({ planning_status: "published" }).eq("id", visitId);
      const { error: e5 } = await sb.from("visit_plans").update({ status: "published", published_at: new Date().toISOString() }).eq("id", planId);
      if (e4 || e5) {
        console.error("[CD-022 publishSingleVisit] status update failed:", (e4 ?? e5)?.message);
        steps.status = "failed";
        return { error: NEUTRAL_WRITE_ERROR, steps, resumeId: planId };
      }
      steps.status = "done";
    }
  }

  {
    const { data: existingNotification } = await sb.from("notifications").select("id").eq("event_key", "assignment").contains("payload", { visit_id: visitId }).maybeSingle();
    if (existingNotification) {
      steps.notification = "done";
    } else {
      const { error: e6 } = await sb.from("notifications").insert({ event_key: "assignment", recipient: assigned_id, payload: { visit_id: visitId }, channel: "push" });
      if (e6) {
        console.error("[CD-022 publishSingleVisit] notification insert failed:", e6.message);
        steps.notification = "failed";
        return { error: NEUTRAL_WRITE_ERROR, steps, resumeId: planId };
      }
      steps.notification = "done";
    }
  }

  redirect(`/visits/${visitId}`);
}

