  const { t, locale } = await useT();
  const tr = (key: string, en: string, ar: string) => locale === "ar" ? ar : t(key, en);
  const sb = await supabaseServer();

  // SCR-WEB-120 is Planner-only (per IMPLEMENTATION_MANIFEST_CD-022.yaml
