      </ul>
      {showInvalid && invalid.length > 0 && (
        <div className="ax-banner ax-banner--warning" role="alert">
          <strong>{strings.invalidTitle}</strong>
          <p>{strings.invalidBody.replace("{n}", String(invalid.length))}</p>
        </div>
      )}
